programs.sol:
"""A spelling-sensitive first-token response.

The component is nearly silent after the first token of a document (or row).
Its biggest response is to the token 'an', with a strong case/spacing effect;
'here' and 'there' also give large positive responses. The remaining initial
response is approximated by broad wordpiece classes: short bare wordpieces,
closed-class English words, other scripts, numbers and punctuation. These
class averages deliberately leave individual wordpiece differences unexplained.
"""
READS = ()

# Articles, conjunctions, prepositions, auxiliaries, and pronouns.
FUNCTION_WORDS = set('''
a the and or but if because as than that this these those
in on at to of for from by with without over under into through about after
before during between within against along around until upon
is are am was were be been being do does did have has had can could will
would shall should may might must not no
i me my mine we us our ours you your yours he him his she her hers it its
they them their theirs who whom whose which what when where why how
'''.split())


def initial_response(text):
    word = text.strip()
    lower = word.lower()
    spaced = text[:1].isspace()
    upper = word[:1].isupper()
    if lower == 'an':
        if spaced:
            return 32.0
        if word.isupper():
            return 29.3
        return 45.1 if upper else 21.3
    if lower == 'here':
        return 16.5 if upper else 3.8
    if lower == 'there':
        return 13.4 if upper else 9.7
    if not word:
        return 0.0
    if word.startswith('<|') and word.endswith('|>'):
        return 0.5
    if word.isdecimal():
        return 0.14
    if not any(c.isalnum() for c in word):
        return -0.24
    if not word.isascii():
        return 1.8
    if not word.isalpha():
        return 0.32
    if lower in FUNCTION_WORDS:
        if spaced:
            return -0.61 if upper else -1.11
        return 0.26 if upper else -0.05
    short = len(word) <= 3
    if spaced:
        if short:
            return 0.7 if upper else 0.6
        return -0.4 if upper else -0.3
    if short:
        return 3.0 if upper else 1.45
    return 1.0 if upper else 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is not None and carry == document:
        return document, 0.0
    return document, initial_response(prefix.token_strings[-1])

"""A small topic/metadata approximation, with document-start corrections.

Issue labels, questions/requests, discussion markers and error words give
negative signals. Opening news/post labels are positive, whereas the colon
in an opening 'Title:' field is strongly negative. The remaining first-token
bias is approximated by token shape and English word frequency; elsewhere
there is a near-zero background. Unrelated lexical spikes are not modeled.
"""
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def topic_value(text):
    word = text.strip(' _./-').lower()
    if not word.isascii() or not word.isalpha():
        return -0.003
    roots = set(wordnet.base_forms(word)) | {word}
    if 'issue' in roots:
        return -0.25
    if roots & {'question', 'request', 'ask', 'please'}:
        return -0.14
    if roots & {'problem', 'post', 'point', 'response'}:
        return -0.11
    if roots & {'error', 'exception', 'failure', 'fault'}:
        return -0.07
    return -0.003


def opening_value(text):
    word = text.strip()
    if word.lower() == 'posts':
        return 2.0 if word.istitle() else 1.35
    if word.lower() == 'news':
        return 1.65 if word.isupper() else 1.35
    if word == 'TV':
        return 1.4
    if word == 'Title':
        return 0.43
    if text.startswith('<|'):
        return -0.36
    if word.isascii() and word.isdigit():
        return 0.54
    if text.startswith('_'):
        return -0.40
    if word.isascii() and word.isalpha():
        common = zipf_frequency(word, 'en') >= 5.5
        if word.islower():
            if text.startswith(' '):
                return 0.29 if common else 0.11
            return 0.05
        if word.isupper():
            if text.startswith(' '):
                return 0.0
            return 0.48 if common else 0.10
        return 0.16 if common else -0.08
    return 0.10


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        age, previous = 0, ''
    else:
        _, age, previous = carry
    state = (doc, age + 1, text)
    if age == 0:
        return state, opening_value(text)
    if age == 1 and previous == 'Title' and text == ':':
        return state, -3.66
    if age == 1 and previous == '#' and text.strip().lower() == 'posts':
        return state, 0.57
    return state, topic_value(text)

programs.haiku:
"""Layer-1 MLP down-projection feature 2817: a mostly-quiet feature with two readable parts.

1. Start of a document (or of a packed row, where the model also starts fresh). With no
   earlier tokens to look at, the value depends only on the token itself:
   - digits: strongly positive;
   - ordinary lowercase words with a leading space (" the", " of", " with"): mildly positive;
   - common function words (the, of, a, in, with, The, In, I, ...): positive;
   - person first names, days and months, and chat/end-of-text markers: negative.
2. Mid-document, words about problems and requests (issue, problem, question, request,
   ask, prompt, post, point, ...) are mildly negative, the bar "⎯" is positive, and the
   colon in "Title:" is strongly negative.
3. Everything else is 0.
"""

READS = ()
FUNCTION_WORDS = set("the a an of in with to and for on by I The In A An It This There What".split())

DIGITS = set("0123456789")
MARKERS = {"<|endoftext|>", "<|im_start|>", "<|im_end|>"}
NAMES_DATES = set(
    "John James William Charles Scott Paul Thomas Mark Adam Sam Josh David Michael "
    "Richard Albert Tom Sarah Bill Edward Anthony Robert Mary Lisa Jennifer Kevin Steve "
    "Monday Tuesday Wednesday Thursday Friday Saturday Sunday January February March "
    "April May June July August September October November December".split()
)
PROBLEM_WORDS = set(
    "issue issues problem problems question questions request requests ask prompt "
    "promise post posts point points response".split()
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    start = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if start:
        if word in DIGITS:
            return carry, 0.55
        if token in MARKERS or word in NAMES_DATES:
            return carry, -0.4
        if token.startswith(" ") and word[:1].islower():
            return carry, 0.25
        if word in FUNCTION_WORDS:
            return carry, 0.45
        return carry, 0.0
    if word.lower() in PROBLEM_WORDS:
        return carry, -0.15
    if token == "⎯":
        return carry, 0.3
    if token == ":" and prefix.token_strings[-2].strip() == "Title":
        return carry, -1.4
    return carry, 0.0

programs.sol:
"""Approximate certain negative code/symbol openings and selected uses of 'one'.

Code openers have large negative values only when they start the available
context (including an initial constant-token run). Further rules approximate
line-initial 1, selected English 'one of', and selected Chinese 一 ('one').
Similar code spellings share amplitudes. Most vocabulary-specific background
responses are deliberately left at zero; this is only a partial reconstruction.
"""
READS = ()

def opening(s):
    if s == '#include':
        return -4.16
    if s.startswith('/*'):
        return -2.7 if s.endswith('\n') else -4.6
    if s in ('//', '///'):
        return -1.9
    if s in ('"""', "'''"):
        return -3.74
    if s in ('"""\n', "'''\n"):
        return -2.68
    if s in ('#!/', '$(', '()', 'test', 'tests'):
        return -2.8
    if s == 'public':
        return -5.89
    if s in ('internal', '\tpublic'):
        return -2.9
    if s in ('const', 'string', 'str'):
        return -2.4
    if s in ('class', 'package', 'using'):
        return -1.0
    if s in ('*', ' *', '__'):
        return -2.3
    if s == ' _':
        return -3.11
    if s == '^^^^':
        return -1.22
    if s == '\x00':
        return -4.25
    return 0.0


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, True, s, '', True)
    _, same, prev, before_prev, blank_line = carry
    same = same and s == prev
    value = 0.0
    if same:
        value = opening(s)
    elif s == '1' and blank_line:
        if '：' in prev:
            value = -1.05
        elif ':' in prev:
            value = -0.50
        elif '\n' in prev:
            value = -0.22
        else:
            value = -0.04
    elif s == ' one':
        word = prev.strip().lower()
        if word in ('which', 'any'):
            value = 0.6
        elif word in ('each', 'every'):
            value = 0.35
        elif word == 'some':
            value = -0.9
        elif word == 'no':
            value = -0.18
    elif (s == ' of' and prev == ' one'
          and before_prev.strip().lower() in ('which', 'each', 'every', 'any')):
        value = 1.6
    elif (s.startswith('一')
          and (prev.endswith(tuple('每同任某哪各又另'))
               or prev in ('单', '單'))):
        value = 1.8
    elif s.startswith(('同一', '每一', '这一', '這一', '另一')):
        value = 0.65
    if '\n' in s:
        blank_line = not s.rsplit('\n', 1)[-1].strip()
    else:
        blank_line = blank_line and not s.strip()
    return (doc, same, s, prev, blank_line), value

"""Local spelling detector for meta-/mega-, beta, and related fragments.

The negative response peaks on a short token that completes 'meta' or 'mega',
not throughout words containing those letters. Whole 'meta'/'mega' pieces
also respond; merged longer words usually do not. Latin, Greek and Cyrillic
spellings are transliterated; script and token size modulate the strength.
Whole 'metal' and 'methane' receive smaller negative values. A positive
exception is the colon of a document-initial 'Title:' field.
"""
import regex
from anyascii import anyascii

READS = ()


def crosses(text, boundary, spelling):
    start = text.rfind(spelling)
    return 0 <= start < boundary < start + len(spelling)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        old, raw_old, age, previous = '', '', 0, ''
    else:
        _, old, raw_old, age, previous = carry
    raw = prefix.token_strings[-1]
    alphabetic = regex.fullmatch(
        r'[\p{Latin}\p{Greek}\p{Cyrillic}\P{L}]*', raw
    )
    current = (anyascii(raw) if alphabetic else raw).lower()
    text = old + current
    boundary = len(old)
    size = len(current)
    latin = not regex.search(r'[\p{Greek}\p{Cyrillic}]',
                             raw_old[-4:] + raw)
    value = 0.0
    word = current.lstrip(' \t\n._/({[<')
    if word == 'meta':
        value = -4.6
    elif word == 'mega':
        value = -5.3
    elif word == 'methane':
        value = -2.0
    elif word == 'metal':
        value = -0.6
    elif crosses(text, boundary, 'meta'):
        value = -7.0 if size <= 2 else -4.2 if size <= 4 else -0.6
        if current.startswith('all'):
            value = -1.5
        elif current.endswith('ol'):
            value = -0.5
        if not latin:
            value *= 0.6
    elif crosses(text, boundary, 'mega'):
        value = -4.0 if size <= 4 else 0.0
        if not latin:
            value *= 0.6
    elif crosses(text, boundary, 'meg') and size <= 2:
        value = -2.7 if latin else -5.5
    elif crosses(text, boundary, 'beta') and size <= 2:
        value = -5.0
    elif old.endswith('et') and current.startswith('a'):
        value = -1.0 if size <= 2 else -0.4 if size <= 4 else 0.0
    if age == 1 and previous == 'Title' and raw == ':':
        value = 7.09
    state = (doc, text[-10:], (raw_old + raw)[-10:], age + 1, raw)
    return state, value

"""Negative pulses for a repeated letter or digit at a token join.

Nonzero doubled digits dominate. Doubled vowels and familiar doubled
consonants are weaker than other consonants. Longer letter fragments,
word boundaries, punctuation gaps and CamelCase weaken the response.
Only the previous two tokens and the current digit-run length are kept.
"""
import math
import re

READS = ()
FIRST_WORD = re.compile(r"([\W_]*)([^\W_]+)")
COMMON_DOUBLES = frozenset("lmnprst")


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, before_previous, digits = "", "", 0
    else:
        _, previous, before_previous, digits = carry
    token = prefix.token_strings[-1]
    state = (document, token, previous,
             min(20, digits + len(token)) if token.isdigit() else 0)
    match = FIRST_WORD.match(token)
    if not match:
        return state, 0.002
    leading, word = match.groups()
    first = word[0]
    stripped = previous.rstrip()
    last = stripped[-1:]
    boundary = "join"
    if not last.isalnum():
        # A single short separator token can intervene: e.g. 2 . 2.
        if (before_previous and previous and len(previous) < 6
                and not any(c.isalnum() for c in previous)):
            last = before_previous[-1:]
            boundary = "space_gap" if previous.isspace() else "gap"
    if first.lower() != last.lower() or not first.isalnum():
        return state, 0.002
    if boundary == "join":
        if any(c.isspace() for c in leading) or previous != stripped:
            boundary = "word_boundary"
        elif leading:
            boundary = "punctuation"

    if first in "0123456789":
        if first == "0":
            strength = 0.06
        elif first == "1":
            strength = 1.92
        elif first == "2":
            strength = 2.85
        elif first == "8":
            strength = 2.67
        elif first == "9":
            strength = 1.17
        else:
            strength = 3.2
        if digits in (2, 3):
            strength *= 0.85
        if boundary == "word_boundary":
            strength *= 0.05
    else:
        letter = first.lower()
        if letter in "aeiou":
            strength = 0.38
        elif letter in COMMON_DOUBLES:
            strength = 1.24
        else:
            strength = 2.9 if first.isascii() else 0.85
        strength *= math.exp(-0.3 * max(0, len(word) - 2))
        capitals = first.isupper() and last.isupper() and word.isupper()
        if first.isupper():
            strength *= 1.5 if capitals else 0.5 if word.isupper() else 0.03
        if boundary == "word_boundary":
            strength *= (1.0 if capitals else 0.1) if len(word) == 1 else 0.01

    if boundary == "punctuation":
        strength *= 0.4
    elif boundary == "space_gap":
        strength *= 0.2
    elif boundary == "gap":
        strength *= 0.1
    return state, -strength

"""Approximate a document-onset pulse.

Training activations concentrate on prefixes with only one distinct token.
Keep a pulse through an initial run of identical tokens, resetting by document.
Estimate its height from token shape, script and named grammatical classes;
once a different token appears, predict zero.  Individual lexical amplitudes
and the small later contextual activations are deliberately left unmodeled.
"""
import regex

READS = ()

# English grammatical classes: (words, lowercase height, capitalized height).
CLASSES = (
    # Personal and object pronouns.
    ('i you he she it we they me him her us them', 7.9, 8.7),
    # Possessive determiners and pronouns.
    ('my your his its our their mine yours ours theirs', 8.7, 13.9),
    # Demonstratives.
    ('this that these those', 3.4, 10.7),
    # Prepositions.
    ('of in on at to for with by from as into onto about above below '
     'under over through between after before during without within', 2.5, 5.1),
    # Conjunctions.
    ('and or but nor if then so although because while when since '
     'unless whether', 3.7, 4.7),
    # Auxiliary verbs.
    ('am is are was were be been being do does did have has had can '
     'could shall should will would may might must', 5.7, 6.2),
)
CLASSES = tuple((frozenset(s.split()), lo, hi) for s, lo, hi in CLASSES)
# Singular definite articles in French, Spanish and Italian.
ROMANCE_ARTICLES = frozenset('le la el il lo'.split())
DECLARATIONS = frozenset(
    'import package class def public private protected function struct '
    'const let var'.split()
)


def onset(s):
    w = s.strip()
    if s.startswith('<|'):
        return 5.4
    if not w:
        if '\n' in s or '\r' in s:
            return 4.7
        return 5.4 if len(s) == 1 else 7.3
    if w.isascii() and w.isdecimal():
        n = int(w)
        if n == 0:
            return 0.1
        if n == 1:
            return 7.9
        return 5.2 if n == 2 else 3.8
    if set(w) == {'#'}:
        return 8.9  # Markdown heading markers.
    # Bullets and star-shaped markers, including decorative repetitions.
    if set(w) <= set('·•∙*') and not s[0].isspace():
        return 14.0 if len(w) > 1 else 5.0
    if not any(c.isalnum() for c in w):
        if '\n' in s:
            return 5.1
        if set(w) <= set('.,:;!?，。！？；：'):
            return -0.4
        return 1.0
    if w.isascii() and w.isalpha():
        capital = w[0].isupper()
        low = w.lower()
        if w == 'I':  # First-person singular pronoun.
            return 13.7 if s[0].isspace() else 22.9
        # The indefinite article, its vowel allomorph, and the definite article.
        if low == 'a':
            return 17.8 if capital else 14.1
        if low == 'an':
            return 10.6 if capital else 5.9
        if low == 'the':
            return 11.9 if capital else 9.4
        if low in ROMANCE_ARTICLES and not w.isupper():
            if capital:
                return 19.0 if s[0].isspace() else 28.0
            return 12.0
        for words, lower, upper in CLASSES:
            if low in words:
                return upper if capital else lower
        if w in DECLARATIONS:
            return 9.7
        # Short capitalized fragments tend to make a larger onset pulse.
        if len(w) <= 3:
            if capital:
                if w.isupper():
                    return 7.5 if len(w) == 1 else 4.5
                return 12.0 if len(w) == 2 else 8.9
            return 7.5 if w[-1] in 'aeiou' else 5.3
        if s[0].isspace():
            return 5.6
        return 5.6 if capital else 3.9
    for script, height in (
        ('Cyrillic', 1.8), ('Han', 4.0), ('Arabic', 4.9),
        ('Greek', 5.7), ('Hangul', 7.9), ('Hiragana', 7.7), ('Katakana', 10.1),
    ):
        if regex.search(r'\p{Script=' + script + '}', w):
            return height
    return 4.4


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, True, onset(prefix.token_strings[-1]))
    elif carry[2] and token != carry[1]:
        carry = (doc, carry[1], False, carry[3])
    return carry, carry[3] if carry[2] else 0.0

programs.haiku:
"""Coordinating conjunctions and list commas that follow a noun.

The component fires on the word that joins two parallel nouns or noun phrases
("policies, procedures, or guidelines"; "the sensitivity and specificity"),
and weakly on the comma that separates items of such a list. It is near zero
when the conjunction joins clauses, adjectives, verbs or numbers.
"""

READS = ()

CONJUNCTIONS = {" and", " or", " AND", " OR", " nor", "/or", " und", " y", " e",
                " et", " и", " ou", " oder", "和", "や", "와", "과", "と"}
LIST_COMMAS = {",", "、"}
FUNCTION_WORDS = {
    "the", "a", "an", "of", "to", "in", "on", "for", "with", "by", "from", "at",
    "is", "was", "are", "were", "be", "it", "that", "this", "as", "not", "up",
    "down", "out", "than", "so", "if", "when", "which", "who", "can", "will",
    "has", "have", "had", "do", "does", "its", "their", "his", "her", "our",
    "your", "my", "we", "they", "he", "she", "you", "i", "one", "more", "about",
}
DETERMINERS = {"the", "a", "an", "its", "their", "his", "her", "our", "your", "these", "such", "various"}
NOUN_ENDINGS = ("tion", "sion", "ity", "ness", "ment", "ance", "ence", "ism", "ics")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    word = prev.strip().lower()
    # the words just before the current token, within the same document
    recent = []
    for i in range(len(prefix.token_strings) - 2, max(-1, len(prefix.token_strings) - 7), -1):
        if prefix.document_ids[i] != prefix.document_ids[-1]:
            break
        recent.append(prefix.token_strings[i].strip().lower())
    noun_like = word.isalpha() and word not in FUNCTION_WORDS and not word.endswith(("ly", "ed", "ive", "ous"))
    in_list = any(w in LIST_COMMAS or w in ("and", "or") for w in recent)
    if tok in CONJUNCTIONS:
        if not noun_like:
            return carry, 0.2
        if word.endswith(NOUN_ENDINGS) or any(w in DETERMINERS for w in recent):
            return carry, 1.3
        return carry, 0.9
    if tok in LIST_COMMAS:
        if noun_like and in_list:
            return carry, 0.5
        if noun_like:
            return carry, 0.2
    return carry, 0.0

programs.sol:
"""A partial lexical/layout approximation, not a single semantic detector.

Negative responses cover spatial directions and specified words/levels.
Positive responses cover some extent phrases, questions about type/size,
and paragraph gaps. Gap strength uses recent language and spacing style.
A few local idioms, number and source-layout rules complete the estimate.
Most other tokens receive zero. All state resets at document boundaries.
"""
import math
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
DETERMINERS = set(
    'the a an this that these those my your his her its our their'.split()
)
LOCATION = set('top bottom above below behind front back left right'.split())
EXTENT = set('length width height depth size shape weight edge end side'.split())
DIRECTIONS = set('north south east west up down in out'.split())
CHINESE_SPATIAL = {'上下', '向上', '往上', '上面', '下面', '前方', '下去', '地下'}
IDIOMS = {
    ('bottom', 'line'): 0.68,
    ('if', 'only'): 0.36,
    ('not', 'always'): 0.18,
    ('the', 'most'): -0.22,
}


@lru_cache(maxsize=20000)
def continental_language_evidence(word):
    """Dictionary frequency advantage over English, clipped to [0, 1]."""
    english = zipf_frequency(word, 'en')
    foreign = max(
        zipf_frequency(word, language)
        for language in ('de', 'fr', 'it', 'es', 'nl', 'pt')
    )
    return max(0.0, min(1.0, (foreign - english - 0.5) / 2))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 0, 0, 0)
    _, previous, before, tail, gaps, spaced, position = carry
    token = prefix.token_strings[-1]
    word, prev, earlier = (
        text.strip().lower() for text in (token, previous, before)
    )
    value = 0.0

    if token.startswith(' ') and word.isalpha():
        value += IDIOMS.get((prev, word), 0.0)
        if word in ('upward', 'upwards', 'inward', 'inwards'):
            value -= 1.42
        elif word in ('downward', 'downwards', 'outward', 'outwards'):
            value -= 0.72
        elif word == 'higher':
            value -= 0.21 + 0.57 * (prev in ('a', 'an', 'the', 'to'))
        elif word in ('inside', 'outside'):
            value -= 0.15 + 1.03 * (prev == 'the')
        elif word in LOCATION:
            value -= 0.09
            if word in ('above', 'below'):
                value -= 0.72 * (prev in ('from', 'far', 'barely', 'just'))
        elif word in ('word', 'words'):
            value -= 0.20
            specified = prev in DETERMINERS or prev in {
                'same', 'following', 'right', 'very', 'all', '’s', "'s"
            }
            value -= 0.69 * (word == 'words' and specified)
        elif word in ('type', 'types', 'size'):
            value += -0.07 + 1.01 * (prev in ('what', 'which'))
        elif word == 'level':
            value -= 0.05
            value -= 0.65 * (prev in {
                'every', 'same', 'a', 'any', 'whatever', 'higher', 'deeper'
            })
