"""layers.1.mlp.down_proj:2824, predicted from the text alone.

What it does: this component goes strongly negative on the word that sets up a complement
about likelihood, risk or suitability, and the preposition that follows it. Examples:
"a good chance [of] being", "at higher risk [of]", "is likely [to] be", "sure [to]",
"perfect [for]", "suitable [for]", and the Chinese words 宜 / 适合 ("suitable"), which
it reads on the word itself. Its weaker negative values are on "instance of", "method of"
and similar. "chance" in the sense of an opportunity ("the chance to") is positive.
Everywhere else it is about zero.

The program has no state: it looks at the current token and the one before it, inside the
same document.
"""

READS = ()

PREPOSITIONS = {"of", "to", "for"}

# "chance" and "chances" before "of": "a good chance of" (strongest).
CHANCE_WORDS = {"chance", "chances"}
# Nouns of risk or probability before "of": "risk of", "probability of".
RISK_NOUNS = {"probability", "probabilities", "likelihood", "risk", "risks"}
# Other nouns of likelihood or danger before "of" or "for".
OTHER_RISK_NOUNS = {"prob", "odds", "incidence", "possibility", "possibilities", "prospect", "danger", "threat"}
# Adjectives of likelihood before "to": "likely to", "apt to", "prone to".
LIKELY_WORDS = {"likely", "unlikely", "apt", "prone", "guaranteed", "certain", "suited", "positioned"}
# Weaker likelihood adjectives before "to".
OTHER_LIKELY_WORDS = {"sure", "bound", "liable", "susceptible", "vulnerable", "inclined", "predicted"}
# Words of suitability or readiness before "for" or "to": "suitable for", "perfect for".
SUITABLE_WORDS = {"suitable", "perfect", "ideal", "good", "great", "potential", "room", "opportunity", "opportunities", "capacity", "ready", "designed", "capable", "known", "available"}
# Words of purpose, method or manner before "of": "instance of", "method of", "way of".
WEAK_WORDS = {"instance", "instances", "method", "methods", "way", "ways", "time", "better", "ease", "signs", "means"}
# Chinese words for suitable, easy and beneficial, one token each.
CHINESE_VALUES = {
    "宜": -8.0, "不宜": -8.0, "适宜": -6.0, "适合": -3.5, "不适合": -3.5, "適合": -3.5,
    "有利于": -3.5, "利于": -3.5, "易于": -3.0, "有益": -3.0,
    "容易": -1.8, "易": -2.0, "有可能": -1.5, "有望": -2.0, "有助于": -1.5, "利": -0.9,
}
ARTICLES = {"a", "an", "the", "any", "every", "no", "your", "this", "rare", "my", "his", "her", "their", "our"}


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return None, 0.0
    word = prefix.token_strings[t].strip()
    prev = prefix.token_strings[t - 1].strip().lower()

    if word in CHINESE_VALUES:
        return None, CHINESE_VALUES[word]
    if word == "chance" and prev in ARTICLES:
        return None, 2.0  # "the chance to": an opportunity, not a probability
    if word not in PREPOSITIONS:
        return None, 0.0

    if prev in CHANCE_WORDS:
        return None, -1.0 if word == "to" else -6.0
    if prev in RISK_NOUNS:
        return None, -4.0
    if prev in OTHER_RISK_NOUNS:
        return None, -2.5
    if prev in LIKELY_WORDS:
        return None, -3.5
    if prev in OTHER_LIKELY_WORDS:
        return None, -2.0
    if prev in SUITABLE_WORDS:
        return None, -1.2
    if prev in WEAK_WORDS and word != "to":
        return None, -0.7
    return None, 0.0

