"""Partial predictor: number endings, document openings, and text formatting.

The digit pairs 30 and 31 give a negative pulse, stronger in dates
and, for 30, after a colon. The first token uses a separate grammar and
formatting baseline, with extra pulses for initial 12 and Title:.
Markup cues account for smaller responses. Other word-specific variation
is left near zero.
"""
import calendar

READS = ()
MONTHS = {s.lower() for s in (*calendar.month_name, *calendar.month_abbr) if s}
PREPOSITIONS = set('of in to with by as about over'.split())
PRONOUNS = set('i you he she we they me him her us them'.split())
POSSESSIVES = set('my your his her our their'.split())
COPULAS = set('is are was were be been being'.split())


def opening(token):
    s = token.strip()
    low = s.lower()
    if s and set(s) == {'#'}:
        return 0.446 if len(s) == 1 else 0.697
    if s == '```':
        return 0.702
    if token.startswith('\\'):
        return -0.46
    if not s:
        if '\t' in token:
            return 0.27
        if '\n' in token:
            return 0.175
        return -0.277 if len(token) == 1 else 0.20
    if s in ('.', ':', ';', ',', '!', '?'):
        return -0.29 if '\n' in token else -0.172
    if s in (')', ']', '}'):
        return -0.30
    if s in ('(', '[', '{'):
        return 0.0
    if s.isascii() and s.isdigit():
        return -0.055
    if low in PRONOUNS:
        return -0.335
    if low in POSSESSIVES:
        return -0.415
    if token.startswith(' ') and low in PREPOSITIONS:
        return -0.337
    if low in COPULAS:
        return -0.17
    if low in ('and', 'but', 'that', 'then', 'than'):
        return -0.284
    if low == 'the':
        return 0.085 if s[0].isupper() else -0.12
    return -0.103


def ordinary(token):
    s = token.strip()
    if token == '<|im_end|>':
        return 0.051
    if s in ('->', '=>', '<<', ':='):
        return 0.05
    if s == '://':
        return 0.069
    if s and set(s) == {'_'}:
        return 0.031
    if s and set(s) == {'='} and len(s) >= 8:
        return 0.08
    if s and set(s) == {'▬'}:
        return -0.096
    if s and set(s) == {'•'}:
        return -0.036
    if token == '\\n':
        return -0.031
    if token == '\\t':
        return 0.039
    return 0.001


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        pos, number, before_number, previous = 0, '', '', ''
    else:
        _, pos, number, before_number, previous = carry

    value = opening(token) if pos == 0 else ordinary(token)
    if pos > 0 and number.endswith('3') and token in ('0', '1'):
        thirty = token == '0'
        value = -0.294 if thirty else -0.176
        if len(number) > 1:
            value = -0.135 if thirty else -0.059
        else:
            context = before_number.strip().rstrip('.').lower()
            if context in MONTHS:
                value = -0.765 if thirty else -0.64
            elif before_number.rstrip().endswith(':'):
                value = -0.395 if thirty else -0.193
    elif pos == 1 and number == '1' and token == '2':
        value = -1.5535
    elif pos == 1 and previous == 'Title' and token == ':':
        value = -2.7281

    if token.isascii() and token.isdigit():
        if not number:
            before_number = previous
        number += token
    else:
        number = ''
    # Retain the last nonblank token so a space does not hide a month name.
    if token.strip():
        previous = token
    return (document, pos + 1, number, before_number, previous), value

"""Approximate a mixture of forum labels and East Asian interval morphemes.

Forum navigation and posting metadata get positive values. The characters
間/间, their compounds, and Korean interval expressions get negative values.
UTF-8 fragments are joined before testing characters; context is a short,
document-local text suffix. Small rules also cover the spelling gian
and doubled middle dots.
Post-like and Slavic appearance/placing fragments get smaller positive
responses. The remaining miscellaneous subword responses are not modeled.
Other tokens are left at zero.
"""
import codecs
import re

READS = ()


def activation(history, s, fragment=False):
    word = s.strip()
    # Forum navigation, counts, and posting labels.
    if word == 'permalink':
        return 16.9
    if word == 'Tags':
        if history.endswith(' Show') or history.endswith('\nShow'):
            return 14.8 if '###' in history[-15:] else 11.4
        if history.endswith(' Hide') or history.endswith('\nHide'):
            return 5.1
    if word == '»' and history.endswith('Home'):
        return 9.0
    if word == 'Posts':
        if history.endswith('#'):
            return 5.8
        if history.endswith('Recommended'):
            return 16.3
        if s == 'Posts':
            if 'Joined:' in history:
                return 5.1
            return 0.8
        return 3.1
    if word == 'Posted':
        return 6.8 if history.endswith('Originally') else 3.9
    if word == 'posted':
        if s == 'posted' and history.endswith('\n'):
            if re.search(r'(?:^|\n)#[^\n]*\n\n$', history):
                return 7.1
            return 3.4
        return 1.1
    if word == 'by':
        if re.search(r'\d[ap]m$', history, re.I):
            return 3.5
        if re.search(r'(?:^|\n)#[^\n]*\n\nposted$', history):
            return 10.4
        if history.endswith('\nposted'):
            return 4.3
        if re.search(r'\b(?:Posted|Post|Posts)\s*$', history):
            return 2.7
    if s == ' .\n\n' and re.search(r'posted by(?: on)?$', history):
        return 17.0
    if word == 'sites' and history.endswith('Share on other'):
        return 5.5
    if word == 'timer' and history.endswith('Show'):
        return 10.5
    if word == 'Statement' and history.endswith('Homework'):
        return 3.9
    # Interval/leisure characters; common merged compounds are weaker.
    if any(c in word for c in '間间閒闲'):
        if word in ('間', '间'):
            if history.endswith('空'):
                return -0.4
            if history.endswith('長い'):
                return -4.0
            if history.endswith(('時', '时', '期', '房', '手')):
                return -4.0
            return -13.0 if fragment else -8.0
        if word in ('閒', '闲'):
            return -5.9
        if word in ('人间', '人間', '世间', '世間', '民间', '民間'):
            return -6.8
        if any(c in word for c in '时時房空'):
            return -0.4 if len(word) == 2 else -0.2
        if '瞬' in word:
            return -1.1
        if word.startswith(('之间', '之間')):
            return -3.0
        if word in ('间的', '間的'):
            return -4.0
        if len(word) >= 3 or word.startswith(('间', '間')):
            return -0.2 if word != '間に' else -3.0
        return -3.0
    # Korean interval syllable gan, during (dongan), between (sai).
    if '간' in word:
        if word != '간':
            return -0.2
        return -11.5 if fragment else -5.8
    if word == '안' and history.endswith('동'):
        return -3.3
    if word in ('사이', '동안'):
        return -4.5 if word == '사이' else -3.3
    # Smaller spelling and punctuation responses.
    if word == 'Gian' or (word == 'ian' and re.search(r'\bg$', history)):
        return -4.9
    # Cognate Slavic stems for appearing and standing/placing.
    if word in ('aw', 'awi') and history.endswith('j'):
        return 2.0
    if word in ('jaw', 'яв'):
        return 2.0
    if (word in ('av', 'aw', 'awi', 'avy', 'ав')
            and history.lower().endswith(('st', 'ст'))):
        return 2.5
    if word == 'став' and history.endswith(('по', 'По', 'до', 'со', 'пред')):
        return 2.5
    if word == 'post' and s == 'post' and history[-1:].isalpha():
        return 2.5
    if word == '··':
        return -0.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', b'')
    _, history, pending = carry
    raw = pending + prefix.token_bytes[-1]
    s, consumed = codecs.utf_8_decode(raw, 'replace', False)
    value = activation(history, s, bool(pending))
    carry = (doc, (history + s)[-160:], raw[consumed:])
    return carry, value

