"""Forum and blog page furniture pushes the activation up: the vBulletin/blog byline
('Posted by', 'Originally Posted by'), the 'Posts' and 'Tags' labels of forum profiles and
collapsible 'Show Tags' headers, 'permalink', and 'Share on other sites'. The CJK/Korean
word for 'between / room / interval' (間, 间, 간) pushes it down, most strongly when it
stands alone as a token. Everything else is predicted as 0."""

READS = ()

FURNITURE = {"permalink": 17.0, " Posted": 6.0, "posted": 5.0, "Posted": 3.6,
             " Posts": 4.6, "Posts": 3.8}
BETWEEN_WORD = {"間": -8.5, "间": -8.5, "閒": -6.0, "간": -6.0}
BETWEEN_COMPOUND = {"之间", "之間", "期间", "期間", "中间", "人间", "民间", "世间", "年间",
                    "之间的", " 사이"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    before = [s.strip().lower() for s in prefix.token_strings[-4:-1]]
    if tok == " Tags":  # '### Show Tags' widget headers are strong; a bare 'Tags' less so
        return None, 14.0 if before[-1:] == ["show"] else 4.0
    if tok in FURNITURE:
        return None, FURNITURE[tok]
    if tok == " sites" and "other" in before:  # 'Share on other sites'
        return None, 5.5
    if "posted" in before:  # the 'by' and the blank name after 'posted by'
        if tok.strip() == "by":
            return None, 6.0
        if tok == " .\n\n":
            return None, 12.0
    if tok in BETWEEN_WORD:
        return None, BETWEEN_WORD[tok]
    if tok in BETWEEN_COMPOUND:
        return None, -4.0
    return None, 0.0

