        previous = previous[1].lower() if previous else ''
        identifier = not token[0].isspace() and not tail[-1:].isspace()
        if value and not identifier:
            verbal_context = previous in {
                'be', 'am', 'is', 'are', 'was', 'were', 'been', 'being',
                'have', 'has', 'had', 'not', 'never', 'already',
                'he', 'she', 'they', 'we', 'i', 'you', 'as', 'than',
