Predict negative values for acronym plurals, less-common split English nouns,
Chinese/Japanese word endings joined to particles, Korean case endings, and
symbols joined to punctuation. A one-character Chinese stem followed by 的
gets a small positive value unless a crossing word is detected. Dictionary matches approximate word
boundaries; individual words and longer-range effects are not reconstructed.
"""
import re
import codecs
from functools import lru_cache
import regex
import cedict
import jmdict
import wordnet
import inflect
INFLECT = inflect.engine()
from wordfreq import zipf_frequency

READS = ()
PARTICLES = frozenset('的为和都上中里是了')

@lru_cache(maxsize=32768)
def known(word, japanese=False):
    return bool(jmdict.glosses(word) if japanese else cedict.glosses(word))

def crossing_word(history, stem, japanese=False):
    """Find a word completed inside this token, without breaking a longer word."""
    previous = max((k for k in range(1, min(6, len(history)) + 1)
                    if known(history[-k:], japanese)), default=0)
    candidates = [k for k in range(1, min(6, len(history)) + 1)
                  if known(history[-k:] + stem, japanese)]
    return any(k >= previous for k in candidates)


@lru_cache(maxsize=32768)
def is_plural_noun(word):
    root = INFLECT.singular_noun(word.lower())
    return bool(root and 'noun' in wordnet.parts_of_speech(root))


@lru_cache(maxsize=32768)
def frequency(word):
    return zipf_frequency(word.lower(), 'en')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history, pending = ('', b'')
    if carry is not None and carry[0] == doc:
        history, pending = carry[1:]
    decoder = codecs.getincrementaldecoder('utf-8')('replace')
    decoder.setstate((pending, 0))
    t = decoder.decode(prefix.token_bytes[-1])
    pending = decoder.getstate()[0]
    value = 0.0
    if (len(t) > 1 and t[-1] in PARTICLES
            and regex.fullmatch(r'\p{Script=Han}+', t)):
        stem = t[:-1]
        cross = crossing_word(history, stem)
        if cross and t[-1] in '的为和都上中里是':
            value = -1.4
        elif cross and t[-1] == '了':
            value = -0.4
        elif len(stem) == 1:
            value = 0.2 if t[-1] == '的' else 0.0
        else:
            value = -0.1 if t[-1] == '的' else 0.0
    elif (len(t) > 1 and t[-1] in 'はがをにへとのでやも'
          and regex.fullmatch(r'[\p{Script=Han}\p{Script=Hiragana}]+', t)):
        if crossing_word(history, t[:-1], japanese=True):
            value = -1.0
        elif regex.search(r'\p{Script=Han}', t):
            value = -0.5 if t[-1] in 'がを' else -0.12
    elif (len(t) > 1 and regex.fullmatch(r'\p{Script=Hangul}+', t)):
        if t[-1] in '을를':
            value = -0.75
        elif t[-1] == '는':
            value = -0.15
    elif (len(t) > 1 and t.isascii() and t.isalpha()
          and t.endswith('s') and history[-1:].isalpha()):
        if t[:-1].isupper() and history[-1:].isupper():
            value = -0.8
        else:
            m = re.search(r'[A-Za-z]+$', history)
            word = (m[0] if m else '') + t
            if is_plural_noun(word):
                if frequency(word) <= 3.5:
                    value = -0.16 if len(word) > 6 else -0.065
                else:
                    value = -0.03
            else:
                value = -0.03 if len(t) <= 6 else 0.0
    elif (len(t) > 1 and t.startswith('%')
          and not any(ch.isalnum() for ch in t)):
        value = -0.95
    elif t.startswith('!/'):
        value = -1.4
    elif len(t) > 1 and t[0] == '#' and t[1] in ',.\n/':
        value = -1.1 if history[-1:] and not history[-1:].isspace() else -0.15
    elif t.startswith("'") and t[1:2] in {'.', '='}:
        value = -1.0
    elif len(t) > 1 and t[0] == '_' and t[-1] in '.;]':
        value = -0.4
    elif t.startswith('++') and len(t) > 2:
        value = -0.6
    elif t.startswith('!') and t.endswith('\n'):
        value = -0.12
    elif len(t) > 1 and not t.strip('·'):
        value = -0.4
    return (doc, (history + t)[-40:], pending), value

"""A document-opening pulse, with its strength set by the kind of token.

The largest activations occur on the first token of a document or packed row.
Alphabetic openers give a negative pulse; numbers and punctuation usually give
smaller ones. English articles, spacing, case, and writing system refine it.
Later tokens are set to zero. Fine word-specific differences are omitted.
"""
import regex

READS = ()


def opening_value(token):
    word = token.strip()
    if not word:
        if '\n' in token:
            return 0.1
        if token == '\t':
            return -2.1
        return 2.54 if token == ' ' else 1.3
    if word.startswith('<|'):
        return 0.27 if word == '<|endoftext|>' else -4.21
    if word.isnumeric():
        return -0.95

    spaced = token[0].isspace()
    lower = word.lower()
    if lower in {'a', 'an', 'the'}:
        if word.istitle():
            if not spaced:
                return -1.45
            return -7.5 if lower == 'the' else -4.5
        if lower in {'a', 'an'}:
            return -11.3 if lower == 'a' else -8.0
        return -6.4 if spaced else -4.0

    if any(ch.isalpha() for ch in word):
        if regex.search(r'\p{Script=Han}', word):
            return -2.65
        if regex.search(r'\p{Script=Cyrillic}', word):
            return -4.7
        if regex.search(r'\p{Script=Hangul}', word):
            return -5.0
        if word.isupper():
            return -2.85
        return -4.05 if spaced or word.istitle() else -3.65

    if '"' in word:
        return -6.2 if spaced else -2.5
    if word == '#':
        return 2.0
    if word.startswith('##'):
        return -2.4
    if word in {'.', ':', '-', '/', '=', '(', ')', '[', ']', '{', '}'}:
        return 0.15 if '\n' in token else 0.4
    if word == ',':
        return -0.6
    if word in {';', '|', '`'}:
        return -1.8
    return -0.9


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    value = opening_value(prefix.token_strings[-1]) if first else 0.0
    return None, value

