"""Doc-start detector with function words split out."""
READS = ()
FUNCTION_WORDS = {" the", " a", " an", " of", " and", " to", " in", " is", " for", " it", " that",
    " on", " or", " with", " by", " as", " was", " at", " from", " be", " are", " this", " which",
    " not", " have", " has", " its", " his", " her", " their", " they", " you", " he", " she", " we"}

def _kind(s):
    if s.strip() == "":
        return "space"
    if s.startswith("<|"):
        return "special"
    body = s.lstrip()
    c = body[:1]
    if c.isdigit():
        return "digit"
    if c.isalpha():
        if s in FUNCTION_WORDS:
            return "function"
        if c.isupper():
            return "cap"
        return "lower"
    return "punct"

VALUE = {"space": 1.2, "digit": -0.9, "punct": -1.1, "special": -4.1, "cap": -3.7, "lower": -3.6, "function": -4.5}

def step(carry, prefix, upstream):
    start = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not start:
        return None, 0.0
    return None, VALUE[_kind(prefix.token_strings[-1])]

programs.sol:
"""A spelling-sensitive end/finality feature, with an opposing Latin-v feature.

The positive side recognizes 終/终 ('end'), some fused Chinese end words,
Korean 종, and the romanizations zhong/jong. The negative side recognizes
v followed by i-heavy fragments, especially split Roman numerals (VIII).
Smaller rules cover 'will/almost always', Ukrainian vi spellings, repeated
middle dots, and a negative document-initial bias. Byte tails handle split
characters; all state resets between documents. This is a spelling-sensitive
approximation, not a general semantic end detector.
"""
import re
import unicodedata
from functools import lru_cache

READS = ()

# Common fused spellings of the Chinese end/finality character.
END_WORDS = {
    '终于': 3.3,       # finally
    '最终': 2.4,       # final / ultimate
    '最終': 2.8,       # traditional spelling of final
    '始终': 1.9,       # throughout / always
    '终身': 4.9,       # lifelong
    '终生': 3.6,       # all one's life
    '终究': 2.4,       # in the end
    '终端': 1.1,       # terminal
    '始终保持': 0.5,   # always maintain
}


@lru_cache(maxsize=16384)
def unaccent(s):
    return ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                   if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    if initial:
        carry = (doc, b'', '', '')
    _, raw, tail, previous = carry
    newest = prefix.token_bytes[-1]
    text = (raw + newest).decode('utf-8', 'ignore')
    text = text[len(raw.decode('utf-8', 'ignore')):]
    token = text.strip()
    normalized = unaccent(text)
    low = normalized.strip()
    joined = (tail + normalized)[-24:]
    value = -0.16 if initial else 0.0

    if token == '終':
        value = 7.8
    elif token == '终':
        value = 5.8
    elif token in END_WORDS:
        value = END_WORDS[token]
    elif tail.endswith(('终', '終')) and ('终' + token) in END_WORDS:
        value = 0.7 * END_WORDS['终' + token]
    elif token == '종':
        value = 2.1
    elif re.search(r'zhong$', joined):
        value = 6.6 if low == 'ng' else 4.8 if low == 'ong' else 2.1
    elif re.search(r'(?<![a-z])jong$', joined):
        value = 0.2 if text[:1].isspace() else 2.1
    elif re.fullmatch(r'[vV][iI]{2,3}', token):
        value = -0.8
    elif token.lower() == 'vim':
        value = -2.7
    elif (re.search(r'vi?$', previous.strip(), re.I)
          and text == token and re.fullmatch(r'[iI]+', token)):
        prev = previous.strip()
        run = len(token) + int(prev.lower().endswith('i'))
        value = -3.0 * min(2, max(0, run - 1))
        if not re.fullmatch(r'[ivxlcdm]+', prev, re.I):
            value *= 0.3
        if prev[-1].isupper() != token[0].isupper():
            value *= 0.5
    elif (previous.strip().lower() in ('v', 'vi')
          and text == token and token.isascii()):
        if low in ('im', 'img'):
            value = -4.8
        elif low.startswith('il'):
            value = -1.5
        elif (low.startswith('i') and len(low) > 1
              and low[1] not in 'nsxtz'):
            value = -0.2
        elif low == 'ui':
            value = -2.3
    elif low == 'always' and previous.strip().lower() in (
            'will', "'ll", '’ll', 'almost'):
        value = 0.5
    elif previous.strip() in ('в', 'В') and token.startswith('і'):
        value = -0.7
    elif len(token) >= 2 and set(token) == {'·'}:
        value = -1.0

    return (doc, (raw + newest)[-3:], joined, text), float(value)

programs.haiku:
"""Responds to the Chinese character 終/终 ("end, final"): strongly on the character
itself, moderately on words built on it that mean "finally, in the end, always"
(最终, 终于, 始终), and on the Korean reading 종 of the same character. Also negative
on a Roman-numeral piece ("III", "II") glued onto a preceding V, as in "XXV|III", and on
runs of middle dots. Everything else is 0."""

READS = ()

END_CHARACTER = {"終": 8.0, "终": 6.0, "종": 1.5}
END_WORDS = {"最终": 2.5, "最終": 3.0, "终于": 3.2, "始终": 2.1, "遂": 1.5}
ROMAN_TAIL = {"III", "iii", "II", "ii"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in END_CHARACTER:
        v = END_CHARACTER[tok]
    elif tok in END_WORDS:
        v = END_WORDS[tok]
    elif tok in ROMAN_TAIL and prev.endswith(("V", "v")):
        v = -6.0
    elif tok == "··":
        v = -1.0
    else:
        v = 0.0
    return carry, v

programs.sol:
"""Approximate a Slavic spelling signal, not a grammatical parser.

Single-letter initial и/і/й is strongly negative; small i-ending syllables
are positive, especially after dental/liquid consonants. There are weaker
rules for Cyrillic а/т and a few conjunctions and focus particles. Latin
a/i get similar rules only in Polish/Czech/Slovak context, estimated from
recent completed words' corpus frequencies. State resets by document.
Split Cyrillic letters are recognized from adjacent bytes. Other effects,
including most differences between individual longer tokens, are omitted.
"""
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()
# Competing languages keep English/Italian a and i near zero.
OTHER_LANGUAGES = ('en', 'de', 'fr', 'es', 'it', 'pt', 'ro', 'hu')
SLAVIC_LANGUAGES = ('pl', 'cs', 'sk')
LANGUAGES = OTHER_LANGUAGES + SLAVIC_LANGUAGES


@lru_cache(maxsize=40000)
def word_frequencies(word):
    return tuple(zipf_frequency(word.lower(), lang) for lang in LANGUAGES)


def update_language(word, scores, mass):
    if len(word) < 2:
        return scores, mass
    frequencies = word_frequencies(word)
    if max(frequencies) < 2.0:
        return scores, mass
    scores = tuple(0.97 * a + b for a, b in zip(scores, frequencies))
    return scores, 0.97 * mass + 1.0


def predict(carry, token, doc):
    if carry is None or carry[0] != doc:
        previous, word = '', ''
        scores, mass = (0.0,) * len(LANGUAGES), 0.0
    else:
        _, previous, word, scores, mass = carry
    for part in regex.findall(r'\p{Latin}+|[^\p{Latin}]+', token):
        if regex.fullmatch(r'\p{Latin}+', part):
            word += part
        else:
            scores, mass = update_language(word, scores, mass)
            word = ''
    split = len(OTHER_LANGUAGES)
    candidates = range(split, len(LANGUAGES))
    slavic_index = max(candidates, key=lambda i: scores[i])
    margin = (scores[slavic_index] - max(scores[:split])) / max(1.0, mass)
    slavic = mass >= 2.0 and margin > 0.2
    language = LANGUAGES[slavic_index] if slavic else 'other'
    bare = token.strip()
    lower = bare.lower()
    boundary = token[:1].isspace() or not previous[-1:].isalpha()
    value = 0.0
    # Initial single-letter fragments versus medial i after a consonant.
    if lower in ('и', 'і', 'й'):
        if boundary:
            value = -5.6 if lower in ('і', 'й') else -3.75
            if bare == 'И' and token[:1].isspace():
                value = -4.2
            if bare.isupper() and not token[:1].isspace():
                value = -6.2
        elif lower != 'й':
            before = previous[-1:].lower()
            if before in 'рлтдс':  # Dental/liquid consonants.
                value = 1.0
            elif before in 'мнцч':  # Nasals and affricates.
                value = 0.5
            if previous[:1].isspace() and len(previous.strip()) == 1:
                value -= 0.45
    elif lower == 'а':
        if boundary:
            value = -1.7 if bare == 'А' and token == bare else -1.1
        elif previous == ' т':
            value = -4.1
    elif boundary and lower == 'т':
        value = -0.6
    elif lower in ('только', 'именно') and boundary:
        value = -1.4
    # Short Cyrillic syllables ending in i.
    elif lower.endswith(('и', 'і')) and len(lower) <= 4:
        before = lower[-2:-1]
        if before in 'рлтдс':
            value = 1.1
        elif before in 'мнцшч':
            value = 0.55
        if token[:1].isspace():
            value *= 0.3
    # The Latin spellings require Slavic language evidence.
    elif slavic:
        if boundary and lower in ('a', 'i'):
            value = -4.7 if lower == 'i' else -3.5
            if language != 'pl':
                value = -6.8 if lower == 'i' else -5.0
        elif boundary and lower == 'in':
            value = -4.5 if language == 'pl' else -6.0
        elif boundary and lower in ('ale', 'aj'):
            value = -1.0 if language == 'pl' else -2.8
        elif lower in ('tylko', 'jen'):
            value = -1.8 if language == 'pl' else -2.8
        elif not boundary and lower.endswith('i') and len(lower) <= 4:
            value = 0.5 if language == 'pl' else 1.8
    return (doc, token, word, scores, mass), value, language


def step(carry, prefix, upstream):
    carry, value, _ = predict(carry, prefix.token_strings[-1],
                              prefix.document_ids[-1])
    raw = prefix.token_bytes[-1]
    if raw == b' \xd0':
        value = -1.8  # A space and the first byte of a Cyrillic letter.
    elif '\ufffd' in prefix.token_strings[-1]:
        same_doc = (prefix.position and
                    prefix.document_ids[-2] == prefix.document_ids[-1])
        if same_doc:
            joined = b''.join(prefix.token_bytes[-2:]).decode('utf-8', 'ignore')
            before_fragment = ''
            older_same_doc = (prefix.position >= 2 and
                              prefix.document_ids[-3] == prefix.document_ids[-1])
            if older_same_doc:
                before_fragment = prefix.token_strings[-3]
            initial = (joined[:1].isspace() or
                       not before_fragment[-1:].isalpha())
            if initial and joined.strip() in ('й', 'Й', 'І'):
                value = -5.6
    return carry, value

"""A signed opening-token response, estimated using familiar text classes.

This models the document-opening effect. Sentence endings, dot leaders,
line breaks and several non-Latin scripts are positive; digits, code-heading
marks and space-prefixed Latin words tend negative. An uninterrupted run of
identical opening tokens keeps the same estimate. Other positions get a
small background value, with corrections for the article "an" and control
markers. Individual words still have unmodeled variation.
"""
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
EASTERN = regex.compile(
    r'[\p{Script=Hiragana}\p{Script=Katakana}'
    r'\p{Script=Hangul}\p{Script=Thai}]')
CYRILLIC_ARABIC = regex.compile(r'[\p{Script=Cyrillic}\p{Script=Arabic}]')


def opening_value(s):
    text = s.strip()
    if text and all(c in '·•' for c in text):
        return 1.8
    if text in ('.', '。'):
        return 0.9 if s.count('\n') > 1 else 1.95
    if text in (';', '?', '!', '-', '–', '—'):
        return 1.0
    if text in ('“', '”'):
        return 2.0
    if EASTERN.search(text):
        return 1.6
    if HAN.search(text):
        return 0.9
    if CYRILLIC_ARABIC.search(text):
        return 0.5
    if '\ufffd' in text:
        return 0.7
    if text.startswith('’') or text == r'\n':
        return 1.1
    if not text:
        if '\n' in s:
            return 1.5 if not s.startswith(' ') else 1.1
        if '\t' in s:
            return 0.94
        return 0.14 if len(s) == 1 else -0.6
    if text.isdigit():
        return -0.3
    if text.startswith('#'):
        return -0.5
    if text.lower() in ('and', 'or'):
        return 1.3 if s.startswith(' ') and not text.isupper() else 0.7
    if text.isalpha() and text.isascii():
        return -0.3 if s.startswith(' ') else 0.05
    return 0.1


def background_value(s):
    # The vowel-form indefinite article and non-text chat/document markers.
    if s == ' an':
        return 0.085
    if s.startswith('<|') and s.endswith('|>'):
        return -0.025
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or doc != carry[0]:
        value = opening_value(prefix.token_strings[-1])
        return (doc, token, True, value), value
    doc, first, repeating, value = carry
    repeating = repeating and token == first
    prediction = (value if repeating else
                  background_value(prefix.token_strings[-1]))
    return (doc, first, repeating, value), prediction

programs.haiku:
"""layers.1.mlp.down_proj:2836 -- a "document start" feature.

What it does: this component is almost silent everywhere except at the first token
of a document (the first token of a row, or the token right after <|endoftext|>).
There the model has no earlier text to lean on, so the component's output is set by
what the first token itself is:
  - a line break ending a sentence, a sentence joiner ("." "-" " and" " or" " with"),
    a CJK character, or a non-ASCII punctuation mark / symbol: strongly positive;
  - a number, a code or markup opener ("#", "import", "/*"), or a bare indent: negative;
  - an English word: slightly negative if it has a leading space, otherwise about zero.
Everywhere else (every position after the first few tokens of a document) it predicts 0.

The values are rough averages read off training data, not a fitted table.
"""

CJK_RANGES = (("぀", "ヿ"), ("㐀", "鿿"), ("가", "힯"))
CODE_START = {"#", "#!/", "/*", "//", "import", "package", "#include", "theorem"}
JOINERS = {".", "-", "and", " and", " or", " with", " but"}


def _is_cjk(text):
    return any(lo <= c <= hi for c in text for lo, hi in CJK_RANGES)


def _value(token):
    """Activation predicted for a document's first token, given its decoded text."""
    core = token.lstrip(" ")
    first = core[:1]
    if token.strip(" \t") == "":
        return -0.5                                # indentation only
    if "\n" in token and first not in ("/", "#", "-", " ", "\t", '"', "'"):
        return 1.5                                 # line break ending a sentence
    if token in JOINERS or core in JOINERS:
        return 1.3                                 # sentence joiners
    if _is_cjk(token):
        return 1.1                                 # Chinese, Japanese, Korean
    if first and not first.isascii() and not first.isalpha():
        return 1.5                                 # non-ASCII punctuation, symbols
    if first.isdigit():
        return -0.3                                # numbers
    if core in CODE_START:
        return -0.6                                # code and markup openers
    if first.isascii() and first.isalpha():
        return -0.2 if token.startswith(" ") else 0.0  # English words
    if first.isascii():
        return 0.3                                 # other ASCII punctuation
    return 0.5                                     # other scripts


READS = ()


def step(carry, prefix, upstream):
    # Document start: the row's first token, or the first token after a document change.
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, _value(prefix.token_strings[-1])
    return None, 0.0

programs.sol:
"""A document-opening title/header detector, with coarse opening-token baselines.

`Title:` gets a large positive pulse on its colon. YAML's initial `title:`
gets a smaller pulse, as does the split initial prefix `Hy` + `dro`.
Opening indentation/escaped whitespace has its own response. Otherwise the
opening token is approximated by its spelling class, and later text by zero.
A repeated opening token keeps the opening response until content changes.
Other lexical and contextual fluctuations are left unmodeled.
"""
READS = ()


def opening_value(token):
    if token == 'Title':
        return 0.652
    if token == '---\n':
        return 0.131
    if token == '\n':
        return -0.539
    if token == '\n\n':
        return 0.038
    if token == '\t':
        return 0.674
    if token == '\\t':
        return 1.943
    if token == '\\n':
        return 0.958
    if token == '\r':
        return 1.021
    if token.startswith('<|') or token.isspace():
        return -0.405
    if not token.isascii():
        return 0.0
    word = token.strip()
    if word.isdigit():
        return -0.313
    if word.isalpha():
