"""Approximate a local b/l spelling response, especially the syllable 'bel'.

Short syllables are strongest; word-internal continuations strengthen them,
while longer suffixes and deeply embedded spellings weaken them. A nearby b
also reinforces an initial l, optionally preceded by a vowel. Belief-word
spellings have an extra response. Fixed transliteration handles accents,
Cyrillic, Arabic and kana; Japanese ru is read as l. Runs of middle dots
are a separate rule. No inference about the meaning of belief is made.
Only the preceding token is remembered, resetting at document boundaries.
"""
import re
import regex
from anyascii import anyascii
from functools import lru_cache

READS = ()
STRENGTH = {
    'bel': -4.1,
    'bol': -1.5,
    'bul': -1.2,
    'bil': -0.6,
    'bal': -0.6,
    'bl': -0.5,
}
UNSUPPORTED = regex.compile(
    r'(?![\p{Latin}\p{Cyrillic}\p{Hiragana}'
    r'\p{Katakana}\p{Arabic}])\p{L}'
)

@lru_cache(maxsize=32768)
def roman(text):
    text = UNSUPPORTED.sub(' ', text)
    text = text.replace('ル', 'l').replace('る', 'l')
    text = text.replace('ъ', 'e').replace('Ъ', 'E')
    text = text.replace('ь', '').replace('Ь', '')
    return anyascii(text).lower()

@lru_cache(maxsize=32768)
def predict(token, previous):
    s, p = roman(token), roman(previous)
    joined = bool(s) and not s[0].isspace()
    value = 0.0
    for syllable, strength in STRENGTH.items():
        at = s.rfind(syllable)
        if at >= 0:
            tail = min(4, len(s)-at-len(syllable))
            weight = (1., .7, .12, .08, .03)[tail]
            if at-(len(s)-len(s.strip())) > 1:
                weight *= .05
            if s[0].isspace():
                weight *= .8
            if joined and s.startswith(syllable) and p and p[-1].isalpha():
                weight *= 1.5
            value += strength*weight
        if joined and s[0].isalpha() and p.endswith(syllable):
            value += strength*.25
    if joined and s[0].isalpha() and 'b' in p:
        match = re.match(r'([aeiou]?)l+', s)
        distance = len(p)-1-p.rfind('b')
        if match and distance < 5:
            vowel = match[1]
            tail = min(2, len(s)-match.end())
            damping = (1., .8, .25)[tail]
            if not vowel and distance == 1 and p[-1] in 'aeiou':
                value += STRENGTH['b'+p[-1]+'l']*.8*damping
            else:
                value += STRENGTH['b'+vowel+'l']*1.6*damping/(1+distance)
    word = (p+s if joined else s).strip()
    if re.search(r'believ(?:e|ed|es|ing)$', word):
        value += -4.8
    if re.search(r'beliefs?$', word):
        value += -2.6
    if token and all(char == '·' for char in token):
        value += -0.9
    return min(0.0, value)

def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), predict(token, previous)

