def lexical_response(token, old):
    word = token.strip(" \t\r\n/._-()[]{}\"'")
    lower = word.lower()
    singular = lower.removesuffix('s')
    if '局' in word:
        return 6.7 if word == '局' else 3.3
    if word == '국':
        return 5.8 if token[:1].isspace() else 3.1
    if singular == 'layout':
        if token.startswith(('/', '.')):
            return 6.0
        return 2.8 if token[:1].isspace() or token.startswith('-') else 4.4
    if singular in ('local', 'locale'):
        return 3.4 if token.startswith('/') else 0.8
    if singular == 'global':
        return 1.1
    if lower == 'bureau':
        return 0.9
    if old and token.isalpha():
        joined = (old + token).lower()
        old = old.lower()
        if joined.endswith(('layout', 'layouts')):
            return 2.6 if lower == 's' else 5.2
        if 'global' in joined and 'global' not in old:
            return 2.3
        for stem in ('local', 'lokal', 'локал'):
            if stem in joined and stem not in old and stem not in lower:
                if 'локаль' in joined:
                    return 6.4
                return 6.3 if joined.endswith(('local', 'lokal')) else 2.2
        for stem in ('loca', 'loka'):
            if joined.endswith(stem) and stem not in old and stem not in lower:
                return 3.4
        if old == 'л' and lower == 'ок':
