    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = lexical_response(token, old)
    match = re.search(r'[^\W\d_]+$', old + token)
    word = match.group()[-40:] if match else ''
    return (doc, word), value

