# (value in a date or citation context, value in other contexts)
YEAR_PAIRS = {"19": (-2.4, -1.5), "20": (-2.2, -1.1)}
DAY_PAIRS = {"30": -0.5, "31": -0.5}  # day-of-month 30/31 after a month, or minutes after ':'
DATE_WORDS = {"in", "In", "from", "since", "born", "until", "late", "early", "of", "the", "(", "al.,",
              "al.", "©", "Cir.", "January", "February", "March", "April", "May", "June", "July",
              "August", "September", "October", "November", "December"}
NON_DATE_WORDS = {"than", "about", "over", "=", "{", "+", "is", "-"}

def step(carry, prefix, upstream):
    t = prefix.position
    if t < 2 or prefix.document_ids[t - 1] != prefix.document_ids[t]:
        return carry, 0.0
    pair = prefix.token_strings[t - 1] + prefix.token_strings[t]
    if prefix.token_strings[t - 2].isdigit():  # digit inside a longer number, e.g. 120 or 2020
        return carry, 0.4 if pair == "20" else 0.0
    if pair in DAY_PAIRS:
        return carry, DAY_PAIRS[pair]
    if pair not in YEAR_PAIRS:
        return carry, 0.0
    m = re.search(r"(\S+)\s*$", prefix.text_prefixes[t - 2])
    word = m.group(1) if m else ""
    strong, weak = YEAR_PAIRS[pair]
    if word in DATE_WORDS or word.endswith("("):
        return carry, strong
    if word in NON_DATE_WORDS:
        return carry, weak * 0.2
    return carry, weak

