def indentation(n):
    if n < 3:
        return 0.10 if n == 1 else 0.0
    if n % 4 == 3:
        return 0.60 if n == 3 else 0.78
    if n % 4 == 1:
        return 0.60 if n == 5 else 0.50
    return 0.48 if n < 12 else 0.68


