        tabs, spaces = text.count('\t'), text.count(' ')
        if first:
            value = 0.8 if not spaces else -0.6
        elif newline:
            value = 0.22 + 0.055 * min(tabs, 5)
        elif spaces:
            value = 0.04 if spaces % 4 == 3 else -0.16
        else:
            value = -0.18
    elif text and text.isspace():
        if '\n' not in text:
            value = -0.065
        elif first and not text.strip('\n'):
            value = 0.52 if len(text) == 1 else -0.6
        elif '\t' in text:
