Mandarin cue, except the common word for requirements (yaoqiu).
UTF-8 pieces are completed before looking up readings. A document's
initial repeated-token run has a negative baseline. Other weak lexical
and context-dependent responses are intentionally left unmodeled.
"""
from functools import lru_cache
import unicodedata
import codecs
import regex
from pypinyin import lazy_pinyin, Style

READS = ()

# Readings, not token identities: the main rising-tone /iu/ syllable and
# several weaker diphthongs.
READING_STRENGTH = {
    'qiu2': 2.7,
    'lou2': 2.0,
    'ou1': 1.25,
    'niu2': 1.1,
}
TONE_MARKS = set('\u0300\u0301\u0303\u0309\u0323')


@lru_cache(maxsize=16384)
def phonetic_value(text):
    word = text.strip()
    if regex.fullmatch(r'\p{Script=Han}+', word):
        reading = lazy_pinyin(word, style=Style.TONE3)[-1]
        if len(word) == 1:
            return READING_STRENGTH.get(reading, 0.0)
        if word.endswith('要求'):
            return 2.6
        if reading == 'qiu2':
            return 0.35
        return 0.0
    if word == '구':
        return 3.0 if text.startswith(' ') else 2.4
    untoned = unicodedata.normalize('NFC', ''.join(
        ch for ch in unicodedata.normalize('NFD', word.lower())
        if ch not in TONE_MARKS
    ))
    if untoned == 'câu':
        return 3.0
    if untoned in ('âu', 'êu', 'ưu'):
        return 0.8
    return 0.0


@lru_cache(maxsize=8192)
def complete_bytes(pending, data):
    decoder = codecs.getincrementaldecoder('utf-8')('replace')
    decoder.setstate((pending, 0))
    text = decoder.decode(data)
    return text, decoder.getstate()[0]


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    token = prefix.token_ids[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        first_token, uniform, previous, pending = token, True, '', b''
    else:
        _, first_token, uniform, previous, pending = carry
        uniform = uniform and token == first_token

    decoded, pending = complete_bytes(pending, prefix.token_bytes[-1])
    sound = decoded if '\ufffd' in text else text

    if text == '<|endoftext|>' and not uniform:
        value = 3.42 if previous.endswith(('.', '!', '?')) else 3.62
    elif uniform:
        if text == '<|endoftext|>':
            value = -0.216
        elif text == '<|im_start|>':
            value = 0.294
        elif text.strip().isdigit():
            value = -0.6
        elif len(text) > 1 and len(set(text)) == 1 and not text.isalnum():
            value = -0.75 if not text.isspace() else -0.4
        else:
            value = -0.26
    else:
        value = 0.002 + phonetic_value(sound)
    if uniform and not text.startswith('<|'):
        value += phonetic_value(sound)
    return (doc, first_token, uniform, text, pending), value

"""Approximate a front-vowel-ending response in European-language text.

Alphabetic token pieces ending in i/e (and related accented or Cyrillic/Greek
letters) get most of the response. Italian/Romanian context strengthens i;
German word-frequency evidence and Bulgarian context give smaller responses.
Language evidence is a decaying average of completed words' corpus
frequencies. English-looking text is mostly quiet. Paired middle dots have
an independent negative response. This is a coarse lexical heuristic, not
an exact recognizer of grammatical suffixes.
"""
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'it', 'ro', 'de', 'fr', 'es', 'nl', 'ru', 'bg',
             'pl', 'cs', 'hu', 'sv', 'fi', 'tr', 'el')


@lru_cache(maxsize=100000)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def response(text, word, continuation, scores):
    bare = ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))
    front_i = bare.endswith(('i', 'и', 'ы', 'η', 'ι'))
    front_e = bare.endswith(('e', 'е', 'ε'))
    if not (front_i or front_e or bare.endswith(('y', 'es'))):
        return 0.0

    english, italian, romanian, german = frequencies(word)[:4]
    language = LANGUAGES[max(range(len(scores)), key=lambda i: scores[i])]
    romance_margin = max(scores[1:3]) - max(scores[0], *scores[3:])
    romanian_margin = scores[2] - scores[1]

    # Strongest case: an alphabetic continuation in Italian/Romanian text.
    if romance_margin > 0.31:
        if not continuation:
            return -0.032 if italian > 5.59 else 0.183
        if front_i:
            if romanian_margin > -2.08:
                return 1.392
            return 0.966 if len(word) <= 8 else 0.607
        return 0.789 if romanian_margin > -1.49 else 0.250

    # A few Italian words can stand out even in otherwise English context.
    if language == 'en':
        return 0.425 if italian - english > 3.50 else 0.0055

    # Attenuate German-looking pieces with a penultimate vowel.
    if german - english > 2.54:
        after_vowel = len(bare) > 1 and bare[-2] in 'aeiou'
        return 0.049 if after_vowel else 0.355

    if scores[8] - scores[7] > 0.51:  # Bulgarian rather than Russian evidence
        return 0.596
    if front_i:
        return 0.022
    if language in ('fr', 'es'):
        return 0.038
    return 0.170 if continuation else 0.066


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', (0.0,) * len(LANGUAGES))
    _, word, scores = carry
    token = prefix.token_strings[-1]
    continuation = bool(word and token and token[0].isalpha())

    # Track only the unfinished word; update language evidence at boundaries.
    for ch in token:
        if ch.isalpha():
            word = (word + ch.lower())[-50:]
        else:
            if len(word) >= 2:
                fs = frequencies(word)
                scores = tuple(0.85*s + 0.15*f for s, f in zip(scores, fs))
            word = ''
    carry = (document, word, scores)
    if token == '··':
        return carry, -1.05
    text = token.strip()
    if not text or not text.isalpha():
        return carry, 0.0
    return carry, response(text, word or text.lower(), continuation, scores)

