def creation_word(text):
    text = text.replace('創', '创')
    if text == '创' or text == '原创':
        return 8.1
    if '创' not in text:
        return 0.0
    # People, abilities and the stock-market board are not acts of creating.
    if text.endswith(('者', '人', '力', '板')):
        return 0.35
    if '创建' in text:
        return 0.4
    if text in ('创下', '开创', '首创'):
        return 4.3
    if text.endswith('创') or text == '创作':
        return 3.2
    if text in ('创业', '创意'):
        return 1.2
    return 1.6


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pending, previous, header, latin = b'', '', False, ''
    else:
        _, pending, previous, header, latin = carry
    raw = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'ignore', False)
    pending = raw[used:]
    word = text.strip()
    value = creation_word(word)
    if word == '창':
        value = 7.3
    elif previous in ('创', '創') and word == '作':
        value = 4.0
    elif previous == '창' and word in ('작', '문'):
        value = 3.2 if word == '작' else 2.2
    elif word == '··':
        value = 1.27
    elif word == ':' and previous == 'Title' and header:
        value = -4.2
    # A related response occurs at the end of split Chinese-name syllables.
    stem = latin.lower().replace("'", '')
    if text == 'uan' and stem.endswith('ch'):
        value = 3.1
    elif text == 'uang' and stem.endswith(('ch', 'sh')):
        value = 1.8
    elif text == 'ong' and stem.endswith(('ch', 'che')):
        value = 1.3 if stem.endswith('ch') else 0.8
    elif text == 'ng' and stem.endswith('tchou'):
        value = 0.55
    match = re.search(r"[A-Za-z']+$", (latin + text)[-32:])
    latin = match.group() if match else ''
    header = word == 'Title' and previous == '<|endoftext|>'
    return (doc, pending, word, header, latin), value

programs.haiku:
"""Creation-word detector: the component fires on the Chinese character 创 (also traditional 創,
and Korean 창), meaning "to create / originate / found", and on words built from it.

It is silent on almost all text. Its strongest responses are the bare character and 原创
("original creation"); it is moderate on words where 创 means "launch / set up / pioneer" or
"create works"; it is weaker on 创新 / 创造 / 创业 (innovate, create, entrepreneurship) and
faint on other words containing the character. Predicted activation: a graded lookup on the
current token's text, 0 everywhere else.
"""

READS = ()

# The bare character (创, 創, Korean 창): the strongest responses.
BARE = {"创", "創", "창"}
# Words where the character carries its "originate / create works / set a record" sense.
STRONG = ("原创", "创作", "創作", "开创", "首创", "创下", "创始", "争创")
# Common innovation / business compounds: moderate-to-weak responses.
WEAK = ("创新", "创造", "创业", "创办", "创立", "创意", "創新", "創造", "創業")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in BARE or token == "原创":
        value = 8.0
    elif any(word in token for word in STRONG):
        value = 4.0
    elif any(word in token for word in WEAK):
        value = 1.7
    elif "创" in token or "創" in token:
        value = 0.5
    else:
        value = 0.0
    return carry, float(value)


def main():
    """Print the predicted activation of each token of a sentence, as a quick check."""
    for token in ("原创", "创", "创新", "创建", "猫"):
        print(token, step(None, _Demo(token), {})[1])


class _Demo:
    def __init__(self, token):
        self.token_strings = (token,)


if __name__ == "__main__":
    main()

programs.sol:
"""A sparse approximation using familiar document-formatting conventions.

The main negative pulses are LaTeX blackboard-bold commands, the first
subheading after a page title, link attributes, and publication/view metadata.
Filled progress bars and repeated comment/table hashes instead pulse positive.
The opening digit sequence 1, 2 is a separate positive response.
Other tokens default to zero. A byte buffer preserves split Unicode characters,
and all state resets at document boundaries.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, n, title, subheading = b'', 0, False, False
    else:
        _, tail, n, title, subheading = carry
    before = tail.decode('utf-8', errors='replace')
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0

    if word == '##':
        if n == 0:
            value = 0.70
        elif not before.strip():
            value = 2.0
        elif re.search(r'(?:^|\n)#(?!#)[^\n]*\n\s*$', before):
            value = -2.6
        elif title and not subheading:
            value = -1.5
        elif re.search(r'##[^\n]*\n\s*$', before):
            value = 1.0
        elif before.endswith(("'", '"')):
            value = -0.7
        subheading = True
    # Chinese source, article, reading, and browsing labels.
    elif word in ('来源', '文章来源', '来源于'):
        value = -1.0
        if before.endswith('本文'):
            value = -3.1
        elif before.endswith(('资料', '資料')):
            value = -1.8
        elif not before.rsplit('\n', 1)[-1].strip():
            value = -2.6
        elif word == '文章来源':
            value = -1.6
    elif word == '本文':
        value = -1.1
    elif word == '阅读':
        value = -0.6
    elif word == '读' and before.endswith('阅'):
        value = -2.6
    elif word == '览' and before.endswith('浏'):
        value = -2.0
    elif word == '源' and before.endswith(('来', '來')):
        value = -2.0
    elif word.lower() == 'views':
        if word == 'Views':
            value = -0.6
            if re.search(r'Replies:?\s*\d+\s*$', before):
                value = -1.4
        elif re.search(r'\d[kK]?$', before):
            value = -0.45
            if re.search(r'\d,\d{3}$', before):
                value = -1.7
        elif '•' in before[-4:]:
            value = -0.5
    elif word in ('http', 'https'):
        if re.search(r'href\s*=\s*\\*[\"\']$', before):
            value = -1.5
        elif re.search(r'src\s*=\s*\\*[\"\']$', before):
            value = -0.6
    # The blackboard-bold LaTeX command is often split into math + bb.
    elif word == 'bb' and before.endswith('\\math'):
        value = -2.3
    elif word in ('array', 'aligned') and before.endswith('\\begin{'):
        value = -1.3 if word == 'array' else -0.5
    elif word == 'array' and before.endswith('\\end{'):
        value = -0.2
    elif word == 'here' and before.rstrip().endswith(('Click', 'click')):
        value = -0.8
    elif word == 'Published' and before.endswith('\n'):
        value = -2.2
    elif word == 'Posted' and before.endswith('\n'):
        value = -0.4
    elif word == 'Keywords' and (before.endswith('\n') or before.endswith('#')):
        value = -1.2
    elif word == 'Created' and re.search(r'/\*\*.*\*\s*$', before, re.S):
        value = -0.9
    elif (len(word) >= 8 and set(word) == {'='}
          and 'Building [' in before[-100:]):
        value = 1.0
    elif (len(word) >= 3 and set(word) == {'█'}
          and re.search(r'%\|$', before)):
        value = 0.5
    elif word == '2' and n == 1 and before == '1':
        value = 2.6

    if word == '#' and n < 3:
        title = True
    tail = (tail + prefix.token_bytes[-1])[-720:]
    return (doc, tail, n + 1, title, subheading), value

"""An attribute-label detector, strongest just after an opening tag's name.

Track HTML/XML/JSX tags, respecting quoted values and JSX braces. Familiar
attribute labels preceded by a space get a large response; later attributes
and labels on indented lines get smaller responses. The XML documentation
pattern <param name gets an extra boost. Bare `name` keys are weaker.
Small side responses cover wiki-table styles, reference-type labels, the
Java package prefix, and runs of middle-dot punctuation. Ordinary text is zero.
"""
import re

READS = ()
ATTRIBUTES = frozenset('''
class classname id name type href src target rel style title alt width height
border align valign content http value placeholder disabled checked selected
multiple required readonly autofocus hidden draggable download size rows cols
role tabindex lang dir charset action method for htmlfor on onclick ref key
data aria xmlns version encoding color bgcolor colspan rowspan v ng fx cref
items open
'''.split())
CORE = frozenset('''
class id name type href src http target value align style color xmlns v ng
'''.split())


def advance(state, token):
    """A tiny markup scanner; quotes outside a tag have no special meaning."""
    name, naming, first, quote, depth = state
    for ch in token:
        if quote:
            if ch == quote:
                quote = None
        elif ch == '<':
            name, naming, first, depth = '', True, True, 0
        elif name is None:
            continue
        elif naming:
            if not name and not (ch.isascii() and (ch.isalpha() or ch == '?')):
                name = None
            elif ch.isascii() and (ch.isalnum() or ch in '_.:-?'):
                name += ch
            elif ch.isspace() and name and name.lstrip('?')[0:1].isalpha():
                naming = False
            else:
                name = None
        elif ch in "\"'":
            quote = ch
            first = False
        elif ch == '{':
            depth += 1
            first = False
        elif ch == '}':
            depth = max(0, depth - 1)
        elif ch == '>' and not depth:
            name = None
        elif not ch.isspace():
            first = False
    return name, naming, first, quote, depth


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        state, text = (None, False, False, None, 0), ''
    else:
        _, state, text = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    name, naming, first, quoted, depth = state
    event = bool(re.fullmatch(r'on[A-Z]\w*', token.strip()))
    label = token.startswith(' ') and (
        word in ATTRIBUTES or event or word == ':'
        or word.startswith(('data-', 'aria-')))
    after_quote = text.rstrip().endswith(('"', "'"))
    after_brace = text.rstrip().endswith('}')
    value = 0.0
    if label and name and not quoted and not depth:
        if first:
            value = 9.0 if word in CORE else 6.0
            if word == 'classname':
                value = 7.5
            if word in ('placeholder', 'lang', 'title', 'alt', 'fx', 'items'):
                value = 4.8
            if word == 'name' and name.lower() == 'param':
                value = 14.3
        else:
            value = 5.5
            if word in ('href', 'id', 'xmlns'):
                value = 6.3
            if word in ('target', 'style'):
                value = 7.8
            if word in ('value', 'colspan', 'rowspan', 'aria', 'items'):
                value = 3.0
        if word == 'ref' or event:
            value = 3.0
        if word == 'checked':
            value = 2.3
        if word == 'on':
            value = 3.0
        if not (first or after_quote or after_brace):
            # Indentation and unquoted/boolean values can separate attributes.
            boundary = re.search(
                r'(?:\n[ \t0-9]*|\t[ \t]*|=\s*[\w.-]+|\bchecked|\bdisabled)$',
                text)
            value *= .55 if boundary else 0.0
    elif label and after_quote and word in {
        'classname', 'href', 'src', 'border', 'width', 'height',
        'target', 'rel', 'colspan', 'bgcolor'
    }:
        value = 3.0
    elif token == ' style' and text.rsplit('\n', 1)[-1].lstrip().startswith(('|', '!')):
        value = 5.0 if after_quote else 1.5
    elif token == 'name':
        value = .8
    elif token == '-type' and text.endswith('{ref'):
        value = 1.2
    elif token == ' com' and re.search(r'\bpackage$', text):
        value = 1.4
    elif len(token) >= 2 and not token.strip('·'):
        value = 1.8
    return (doc, advance(state, token), (text + token)[-160:]), value

"""A small approximation of a weak number/formatting response.

A period after a short digit run is usually negative. Probable numbered-list
markers, long integers and already-dotted numbers receive smaller responses.
There are also small code-punctuation effects and document-opening baselines.
Individual words' otherwise irregular responses are not memorized.
"""
import re

READS = ()


def response(token, before, first):
    word = token.strip()
    if first:
        if token == '.':
            return -0.085
        if word == '#':
            return -0.177
        if token == '#include':
            return 0.219
        if token == 'import':
            return 0.401
        if token.isascii() and token.isdigit():
            return -0.078
        if token.isascii() and token.isalpha() and not token.isupper():
            return 0.084

    if token == '.':
        number = re.search(r'[0-9]+$', before)
        if number:
            left = before[:number.start()]
            line = left.rsplit('\n', 1)[-1].strip()
            if len(number.group()) >= 4 or line in ('', '(', '['):
                return -0.005
            if left.endswith('.'):
                return -0.026
            return -0.096
    if token.isascii() and token.isdigit():
        return -0.005
    if token == '://':
        return 0.101
    if word == 'import':
        return -0.047
    if word == '#include':
        return -0.018
    if token == '</think>':
        return -0.073
    if word and set(word) == {'='}:
        return -0.015
    if word == ':':
        return -0.011
    if word == '#':
        return -0.015
    return -0.001


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    before = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = response(token, before, first)
    return (document, (before + token)[-128:]), value

