"""Water detector: fires on words for water, and words for water-related things
(bodies of water, soaking/rinsing, drops, blood), strongly after a modifier and weakly
after a determiner such as 'the' or 'a'."""
READS = ()

WATER_WORDS = {
    "water": 1.5, " waters": 1.1, "waters": 1.1, "水": 0.5, "水量": 1.4, "浇水": 1.3, "海水": 1.8,
    "河": 1.2, "海洋": 1.1, "塘": 2.0, "湖": 0.3, " ocean": 1.0, " Ocean": 0.5, " ponds": 0.5,
    " pools": 0.7, " Fountain": 2.9, "Fountain": 2.9, " boat": 0.5, "船": 0.5, "舟": 0.5,
    "泡": 0.7, "濯": 2.5, "滴": 2.0, "血": 1.0, " drain": 0.6, " bottle": 0.9, "瓶": 1.0,
    "壶": 1.0, " drink": 0.3, " beverage": 0.4, "饮": 0.4, "飲": 0.4, " saline": 0.7,
}
DETERMINERS = {" the", " a", " an", " of", " and", " or", " in", " this", " that", " its", " his", " her", " our", " your", " my"}


def step(carry, prefix, upstream):
