programs.sol:
"""Local grammatical links, with a separate document-start baseline.

Positive rules cover Chinese copulas, becoming and satisfying needs, Japanese
nominalized clauses and topic/subject particles, Korean particles, and "something".
Chinese aspect/result markers use the preceding token's length and verb reading.
Clause punctuation and certain modals/adverbs enhance some links. Dictionary
glosses identify verbs and words meaning "satisfy".
Adjacent runs of middle dots are negative. Most other positions are near zero.
A document's first token instead receives a negative script-dependent baseline.
"""
from functools import lru_cache
import cedict
import opencc
import regex

READS = ()
SIMPLIFY = opencc.OpenCC('t2s')

# Named closed-class grammatical constructions: strength and spellings.
MARKERS = {
    'copula': (0.810, '是 都是'.split()),
    'emphatic_copula': (1.782,
        ('也是 才是 更是 既是 已是 仍是 将是 '
         '这也是 同时也是 一直都是').split()),
    'this_that_it_is': (1.400, '这是 那是 它是'.split()),
    'benefactive': (0.411, '为 也为'.split()),
    'relation_marker': (0.217, '于 作为 对 给'.split()),
    'continuing_aspect': (0.467, '着 著'.split()),
    'completed_aspect': (-0.169, '了 了一 了一个'.split()),
    'result_complement': (0.112, '出 成 到 起'.split()),
    'indefinite_classifier': (0.353, '一场 一段 一种 一条'.split()),
    'japanese_は': (0.635, 'は'.split()),
    'japanese_が': (0.485, 'が'.split()),
    'japanese_も': (0.389, 'も'.split()),
    'japanese_quotative': (0.551, 'という'.split()),
    'japanese_nominalized_topic': (0.559, 'のは のが のも というのは というのが'.split()),
    'korean_topic': (0.402, '은 는'.split()),
    'korean_subject': (0.257, '이 가'.split()),
}

ADVERBS = ('进一步', '不断', '同时', '已经', '努力', '共同',
           '也', '已', '正', '将', '要', '能', '可', '都')

@lru_cache(maxsize=32768)
def token_features(raw):
    s = raw.strip()
    han = bool(s and regex.fullmatch(r'\p{Script=Han}+', s))
    if han:
        s = SIMPLIFY.convert(s)
    f = {name: strength for name, (strength, words) in MARKERS.items()
         if s in words}
    if s.lower() == 'something':
        f['indefinite_thing'] = 0.294
    if s and set(s) == {'·'} and len(s) > 1:
        f['middle_dot_run'] = 0.0
    if s.endswith(('ことは', 'ことが', 'ことも', 'ことを')):
        f['japanese_nominalized_clause'] = 0.992
    if not han:
        return f
    f['chinese'] = 0.0
    if s.startswith('是一'):
        f['copula_classifier'] = 0.789
    elif s.startswith('是') and s[1:] in ('我', '你', '他', '她', '我的',
                                         '中国', '最', '非常'):
        f['copula_complement'] = 1.024
    if s.endswith('成为') or s.endswith('成为了'):
        f['become'] = 1.991
    stem = s
    if len(stem) > 1 and stem.endswith(('了', '着')):
        stem = stem[:-1]
        f['aspect_suffix'] = 0.364
    glosses = cedict.glosses(stem)
    if not glosses:
        for adv in ADVERBS:
            if stem.startswith(adv) and len(stem) > len(adv):
                glosses = cedict.glosses(stem[len(adv):])
                if glosses:
                    break
    if any(g.startswith('to ') for g in glosses):
        f['dictionary_verb'] = 0.008
    gloss = '; '.join(g for g in glosses
                      if g.startswith(('to ', '(fig.)'))).lower()
    if len(stem) >= 2 and ('to satisfy' in gloss or 'to meet (the needs' in gloss):
        f['satisfy'] = 1.304
    return f

@lru_cache(maxsize=32768)
def previous_properties(raw):
    s, f = raw.strip(), token_features(raw)
    return {
        'clause_boundary': bool(s and s[-1] in '，,；;：:'),
        'modal_or_adverb': s in ('将', '能', '能够', '可以', '努力', '共同', '进而'),
        'verb': 'dictionary_verb' in f,
        'multi_han': 'chinese' in f and len(s) >= 2,
        'dot': bool(s and set(s) == {'·'}),
    }

def linked_value(raw, previous):
    f, p = token_features(raw), previous_properties(previous)
    value = -0.0002 + sum(f.values())
    if 'continuing_aspect' in f or 'completed_aspect' in f:
        value += 0.425 * p['verb']
        value += 0.352 * p['multi_han']
    if 'copula' in f and p['clause_boundary']:
        value += 1.388
    if 'benefactive' in f:
        value += 0.888 * p['clause_boundary']
        value += 0.621 * p['modal_or_adverb']
    if 'result_complement' in f and p['multi_han'] and p['verb']:
        value += 0.376
    if 'middle_dot_run' in f and p['dot']:
        value += -2.552
    return value

def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        s = raw.strip()
        if s.startswith('<|'):
            value = -0.03
        elif s and regex.fullmatch(r'\p{Script=Han}+', s):
            value = -0.74
        else:
            value = -0.32
    else:
        value = linked_value(raw, carry[1])
    return (doc, raw), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:2851 -- a "predicate-introducing word" detector in Chinese text.

What it responds to: the word that introduces the predicate of a sentence, after its
subject. Chosen by hand from the strongest activations:
  * copulas: 是 and compounds (也是, 都是, 这是, 更是, 正是 ...). Strongest right after a
    comma, i.e. after a comma-separated subject ("未来的五年，是 ..."); weaker elsewhere.
  * "become / serve as" verbs: 成为, 成為, 变成, 堪称, 事关 (strong everywhere).
  * formal-register predicate verbs of achievement and policy prose: 为, 实现, 提高,
    促进, 满足, 解决, 形成, 发挥, 推动, 体现, 创造, 构建 ... (moderate; stronger after a comma).
  * aspect markers 了 / 着 / 过 right after a Chinese character (a verb + 了/着).
  * subject/topic particles in Japanese and Korean (は, が, も, 은, 는, 이, 가).
Everything else predicts 0, except the first token of each row or document, where the
component is reliably negative (its context is reset, so it is treated as an outlier).

Values are rounded from least-squares fits on training rows. Scaling them down to 0.7x
made the e2e score worse on eval, so they stay at full scale.

Main program: step() walks one token at a time and needs only the current token and the one
before it, so it has no carry.
"""
READS = ()

COPULA = {'是', '也是', '都是', '这是', '这也是', '是我', '它是', '已是', '更是', '正是', '就是', '又是', '将是'}
BECOME = {'成为', '成為', '变成', '堪称', '事关'}
VERBS = {'为', '作为', '实现', '提高', '提升', '促进', '满足', '解决', '营造', '打破', '筑牢', '形成', '培养',
         '发挥', '推动', '增加', '具有', '象征', '凝聚', '加快', '影响', '体现', '展现', '得到', '创造', '构建',
         '践行', '谱写', '打响', '感受到', '共同', '减少', '打造', '推进', '带动', '赢得', '取得', '保障'}
ASPECT = {'了', '着', '著', '过'}
PARTICLES = {'は', 'が', 'も', '은', '는', '이', '가', 'という'}
CLAUSE_END = {'，', '、', '）', ',', '。'}


def is_han(s):
    """True if the token is made only of CJK ideographs."""
    return len(s) > 0 and all('一' <= c <= '鿿' for c in s)


def step(carry, prefix, upstream):
    t = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, (-0.76 if is_han(t) else -0.32)
    prev = prefix.token_strings[-2]
    comma = prev in CLAUSE_END
    if t in COPULA:
        return None, 2.8 if comma else 0.9
    if t in BECOME:
        return None, 2.9
    if t in VERBS:
        return None, 1.3 if comma else 0.8
    if t in ASPECT and is_han(prev):
        return None, 0.5
    if t in PARTICLES:
        return None, 0.5
    return None, 0.0

programs.sol:
"""A small orthographic approximation to sparse positive activations.

These case patterns recur in high-activation windows. An isolated lowercase
vowel following two or more capitals gets a larger score; plural s does not.
Common English two-letter words are quieter than uncommon fragments.
There are smaller rules for document starts, reversed case, and <think>.
Fullwidth Latin tokens are normalized. State is the document label and a
capital-run count capped at two; the count resets at document boundaries.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=50000)
def response(text, capitals, first):
    if first:
        if text[:1].isupper():
            return 0.43 if len(text.strip()) == 1 else 0.58
        if len(text) == 1 and text.isascii() and text.islower():
            return 0.05
        return 0.22
    if text == '<think>':
        return 0.28

    # A one-letter continuation of a capitalized abbreviation or fragment.
    if (capitals and len(text) == 1 and text.isascii()
            and text.islower()):
        if text == 's':
            return 0.02
        if text in 'aeiou':
            return 3.45 if capitals >= 2 else 1.25
        return 0.98 if capitals >= 2 else 0.52

    pair = re.fullmatch(r'[\W_]*([A-Z][a-z])', text)
    if pair:
        pair = pair[1]
        if capitals >= 2 and text.startswith('-'):
            return 2.71
        if capitals and text[:1].isupper() and pair[1] in 'aeiou':
            return 2.38
        frequency = zipf_frequency(pair, 'en')
        if pair[1] in 'aeiou':
            return 0.03 if frequency >= 5.3 else 0.41
        if pair[1] == 'y' and frequency < 5.3:
            return 0.28
        if frequency < 4.0:
            return 0.08
    if re.fullmatch(r'[\W_]*[a-z][A-Z]', text):
        return 0.23
    return -0.001


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    capitals = 0 if first else carry[1]
    text = unicodedata.normalize('NFKC', prefix.token_strings[-1])
    value = response(text, capitals, first)
    suffix = re.search(r'[A-Z]+$', text)
    if suffix:
        length = len(suffix[0])
        capitals = min(2, length + (capitals if suffix.start() == 0 else 0))
    else:
        capitals = 0
    return (document, capitals), value

"""Approximate a framing-phrase boundary signal.

Commas closing introductory prepositional, temporal, or adverbial phrases
receive a positive response; ordinary list commas stay weak. Common auxiliary
verbs, subject pronouns, code-like syntax, and unfinished brackets
reduce the response. State is a short fragment plus the preceding frame's
strength, used for numeric date continuations. Time nouns and subject onsets
can receive a smaller response. Small token-specific fluctuations are omitted.
"""
import re
import calendar
import wordnet
READS = ()

# Prepositions and other adjunct openers, including some European forms.
OPENERS = set('''in on at by from under during throughout after before
following with without within upon for to as according despite besides
between over through towards toward alongside among beyond outside across
inside into around since until past near above below behind against via
using given based compared regarding concerning prior along out post up
en dans para sobre nos nesse de por durante entre sob pendant apres
avant avec depuis selon sous après à al'''.split())
DISCOURSE = set('''however therefore thus hence also first second third
alternatively moreover indeed yes no well nevertheless consequently
furthermore finally then'''.split())
MODIFIERS = set('''and but so just only even while wait hmm perhaps maybe
suppose assuming right more most less very early late shortly nearly almost
particularly especially also sometime somewhere else'''.split())
TEMPORAL = set('''time times day days week weeks month months year years
night nights century centuries period periods season seasons moment
moments hour hours minute minutes second seconds decade decades morning
evening afternoon weekend weekends'''.split())
FRAMING_ADVERBS = set('''today yesterday tomorrow now later earlier recently
previously initially currently nowadays here herein there thereafter
subsequently meanwhile afterwards together soon'''.split())
AUXILIARIES = set('''is are was were be been has have had will would can could
should must shall does did do am'''.split())
SUBJECTS = {'he','she','we','they','i','you','it','there'}
WEAK_CLAUSES = {'if','when','once','because','although','since','unless'}
MONTHS = {name.lower() for name in calendar.month_name if name}
MONTHS |= {name.lower() for name in calendar.month_abbr if name}
WORDS = re.compile(r"[A-Za-zÀ-ÿ]+")


def phrase_strength(text):
    words = WORDS.findall(text)
    low = [w.lower() for w in words]
    # A frame may begin an embedded clause: "we find that in this case,...".
    embedded = False
    for i in range(len(low)-1):
        if low[i] in {'that','because','whereas','then'}:
            if low[i+1] in OPENERS | FRAMING_ADVERBS:
                words, low = words[i+1:], low[i+1:]
                embedded = True
                break
    while low and (low[0] in MODIFIERS
                   or len(low[0]) == 1 and low[0] not in OPENERS | {'a','i'}):
        words, low = words[1:], low[1:]
    if not low:
        return 0.0
    # Headings and numbered paragraphs can run directly into a new frame.
    for i, w in enumerate(words):
        if i and w[:1].isupper() and low[i] in OPENERS:
            text = text[text.find(w):]
            words, low = words[i:], low[i:]
            break
    first = low[0]
    if first in OPENERS:
        score = 4.0
        if first in {'to','for','with','as'}:
            score = 2.8
        if first in WEAK_CLAUSES:
            score = 1.2
    elif first in FRAMING_ADVERBS:
        score = 4.8
    elif first in DISCOURSE:
        score = 0.9
    elif (first.endswith('ly') and 'adverb' in wordnet.parts_of_speech(first)
          or first.endswith('ment') and not wordnet.parts_of_speech(first)):
        score = 4.5
    elif first in WEAK_CLAUSES:
        score = 1.0
    else:
        score = 0.0
    # Bare time noun phrases: "each year", "a few days later", "this week".
    bare_time = (first in {
        'last','next','this','that','each','every','a','an','some','the','about'}
        and any(w in TEMPORAL for w in low[:7])
        and low[-1] in TEMPORAL | {'ago','later','earlier','before','after'})
    if bare_time:
        score = max(score, 4.5)
    if (first in OPENERS or score > 3) and (
            any(w in TEMPORAL | MONTHS for w in low)
            or re.search(r'\b[12][0-9]{3}\b', text)):
        score = max(score, 5.2)
    if first in {'this','that','each','the','some'} and any(
            w in {'way','manner','case','respect','sense'} for w in low[:3]):
        score = max(score, 4.0)
    if low[:2] == ['since','then']:
        score = 3.0
    if low[:2] in (['for','example'], ['for','instance']):
        score = 0.5
    if low[:2] == ['after','all']:
        score = 1.1
    if bare_time and words[0].islower():
        score *= 0.4 if first == 'the' else 0.75
    if first in OPENERS and not embedded and words[0].islower():
        score *= 0.7
    if any(w in AUXILIARIES for w in low[1:]):
        score *= 0.25
    if (any(w in {'he','she','we','they','i'} for w in low[1:])
            or any(w in SUBJECTS for w in low[2:])):
        score *= 0.25
    if 'import' in low or re.search(r'[_`]|range\(', text):
        score *= 0.15
    if any(text.count(a) > text.count(b)
           for a,b in [('(',')'),('[',']'),('{','}')]):
        score *= 0.08
    return score * max(0.3, 1.0 - len(low) / 55)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, fragment, previous = carry
    token = prefix.token_strings[-1]
    if '<|endoftext|>' in token:
        return (doc, '', 0.0), 0.0
    value = -0.006
    for part in re.split(r'([,，、،.!?;:\n。！？：；])', token):
        if not part:
            continue
        if part in ',，、،':
            score = phrase_strength(fragment)
            if not WORDS.search(fragment) and re.search(r'\d', fragment):
                score = max(score, 0.75 * previous)
            chinese = fragment.strip()
            if len(chinese) < 45 and chinese.startswith((
                    '在','从','從','于','於','自','每','早在','截至',
                    '多年来','多年來')):
                score = max(score, 4.2)
            if part == '،' and chinese.startswith((
                    'في ', 'وفي ', 'ففي ', 'بعد ', 'خلال ')):
                score = max(score, 3.5)
            if re.search(r'(?:后|後|之后|以後|时|時)$', fragment.rstrip()):
                score = max(score, 2.8)
            value = 0.10 + score
            if part == '、':
                value = max(value, 0.8)
            previous, fragment = score, ''
        elif part in '.!?;:\n。！？：；':
            last = WORDS.findall(fragment.lower())
            if part == '.' and last and last[-1] in {
                    'fig','eq','dr','mr','mrs','ms','etc','a','p','m'}:
                fragment += part
            elif part == '\n' and not WORDS.search(fragment):
                fragment = ''
            else:
                fragment, previous = '', 0.0
        else:
            fragment = (fragment + part)[-260:]
    # Phrase completion can be marked by a time noun or the start of its subject.
    if value == -0.006:
        word = token.strip().lower()
        if word in SUBJECTS | {'the', 'a'} and len(WORDS.findall(fragment)) == 1:
            value = 0.07 * previous
        if word in TEMPORAL or word in SUBJECTS:
            score = phrase_strength(fragment)
            if len(WORDS.findall(fragment)) > 2:
                value = 0.18 * score
    return (doc, fragment, previous), float(0.8 * value)

programs.haiku:
"""Layer 1 MLP down_proj component 2853 fires on the comma that closes a fronted adverbial
at the start of a sentence, e.g. "In 2008," / "On October 1," / "Through play," / "However,".
Strongest for short prepositional intros (3-6 tokens), moderate for single adverbs,
near zero when the sentence opens with a subject, and weak for later adjunct commas."""
READS = ()

FRONTERS = set("on in at after to with for during throughout by following upon within from under among across between into through over about given according based apart as".split())
CLAUSE = set("if since because when while once until before although unless whenever whereas".split())
ADVERBS = set("furthermore alternatively also first then thus therefore so now however finally moreover additionally consequently specifically still indeed instead meanwhile overall but and fortunately".split())
SUBJECTS = set("the a an it this that he she they we i you there these those his her their our my your its".split())
COMMAS = {",", "，", "、"}


def phrase_strength(n):
    # length of the fronted phrase in tokens: short intros are strongest
    if n <= 1:
        return 1.5
    if n <= 6:
        return 3.0
    if n <= 11:
        return 1.2
    return 0.7


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "sent_first": None, "sent_len": 0, "commas": 0,
                 "seg_first": None, "seg_len": 0}
    if any(ch in text for ch in ".!?;:\n"):
        return {"doc": doc, "sent_first": None, "sent_len": 0, "commas": 0,
                "seg_first": None, "seg_len": 0}, 0.0
    word = text.strip().lower()
    if text.strip() in COMMAS:
        value = 0.0
        if carry["commas"] == 0:
            first = carry["sent_first"] or ""
            if first in FRONTERS:
                value = phrase_strength(carry["sent_len"])
            elif first in ADVERBS or first.endswith("ly"):
                value = 1.4 if carry["sent_len"] <= 3 else 0.6
            elif first in CLAUSE:
                value = 0.3
            elif first in SUBJECTS:
                value = 0.0
            else:
                value = 0.4
        elif carry["seg_first"] in FRONTERS:
            value = 0.8 * phrase_strength(carry["seg_len"])
        else:
            value = 0.1
        carry["commas"] += 1
        carry["seg_first"], carry["seg_len"] = None, 0
        return carry, float(value)
    if word:
        if carry["sent_first"] is None:
            carry["sent_first"] = word
        carry["sent_len"] += 1
        if carry["seg_first"] is None:
            carry["seg_first"] = word
        carry["seg_len"] += 1
    return carry, 0.0

programs.sol:
"""An A-initial word-fragment detector.

The strongest negative predictions are inside uncommon words starting with A
(also accented A, Cyrillic а and Greek alpha).  The effect fades as letters
accumulate and is small when the spelling becomes a familiar English word.
There are weaker effects on whole A-words and on the following word, especially
between two capitalized words.  Only the unfinished word is carried forward.
"""
import math
import unicodedata
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()
LETTERS = regex.compile(r'\p{L}+')
LAST_WORD = regex.compile(r'\p{L}+$')


def starts_a(word):
    if not word:
        return False
    first = unicodedata.normalize('NFD', word[0]).lower()[0]
    return first in 'aаα'


@lru_cache(maxsize=32768)
def familiarity(word):
    return zipf_frequency(word, 'en')


def rarity(word):
    return min(1., max(0., (6. - familiarity(word)) / 4.))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, initial = '', ''
        first_position = True
    else:
        _, word, initial = carry
        first_position = False
    token = prefix.token_strings[-1]
    letters = LETTERS.match(token)
    continuation = bool(word and letters)
    stripped = token.lstrip()
    capital = bool(stripped and stripped[0].isupper())
    value = 0.

    if continuation and starts_a(word):
        spelling = word + letters[0]
        known = min(1., max(.05, (5. - familiarity(spelling)) / 2.))
        fade = math.exp(-.18 * len(initial) - .20 * (len(word)-len(initial)))
        value = fade * known * (-1.48 - .57 * word[0].isupper())
    else:
        if not continuation and starts_a(stripped):
            value += rarity(stripped) * (
                -.265 - .049 * capital - .133 * (not token[:1].isspace()))
            value += .458 * first_position
        if token[:1].isspace() and LETTERS.match(stripped) and starts_a(word):
            previous_capital = word[0].isupper()
            value += rarity(word) * (
                -.058 + .014 * previous_capital + .077 * capital
                - .292 * previous_capital * capital)

    tail = LAST_WORD.search(token)
    if tail:
        if continuation and tail.start() == 0:
            word += tail[0]
        else:
            word = initial = tail[0]
    else:
        word = initial = ''
    return (doc, word, initial), float(value)

"""Partial approximation using readable local lexical patterns.

Strong negative pulses mark references to following statements, selected
multiple-choice/list phrases, and a few Chinese list, name, and opacity
constructions. Smaller baselines cover reference words, punctuation, chat
markers and dot leaders. Document starts use script and surface form instead.
A 100-character tail supplies context and resets at each document boundary.
Most of the component's token-specific variation is not captured by these rules.
"""
import re
import regex

READS = ()

DEFINITE = frozenset(('this', 'that', 'these', 'those', 'my', 'your',
                      'his', 'her', 'its', 'our', 'their'))
UNIVERSAL = frozenset(('all', 'any', 'every', 'each', 'both', 'either',
                       'neither'))
INDEFINITE = frozenset(('some', 'several', 'various'))


def background(token):
    w = token.strip().lower()
    if w in DEFINITE:
        return -0.011
    if w in UNIVERSAL:
        return -0.016
    if w in INDEFINITE:
        return 0.057
    if token in ('<|im_start|>', '<|im_end|>'):
        return -0.03
    if token == '<think>':
        return 0.13
    if token == '</think>':
        return 0.07
    if len(w) >= 2 and set(w) <= {'·'}:
        return -0.45
    if token == '$':
        return 0.075
    if token == '=':
        return -0.033
    if token == '?':
        return 0.032
    if token == ',':
        return 0.004
    if token == ':':
        return 0.011
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        tail = ''
        first = True
    else:
        tail = carry[1]
        first = False
    w = token.strip().lower()
    old = tail.lower().rstrip()
    value = background(token)
    if first:
        # Without preceding text, script and surface form dominate this estimate.
        value = -0.020
        if token.strip().isalpha():
            if regex.search(r'\p{Script=Han}', token):
                value -= 0.195
            if w in ('a', 'an', 'the'):
                value += 0.124
        elif token.strip():
            if not any(ch.isalnum() for ch in token):
                value -= 0.145
            if w in (',', ';', ':'):
                value += 0.136
            if '<|' in token or token.startswith(('<think', '</think')):
                value -= 0.196
    elif old.endswith('following'):
        question = bool(re.search(r'(which|what) (?:one )?of the following$', old))
        if w in ('statement', 'statements'):
            value = -2.0 if question else -1.05
        elif w in ('choice', 'choices', 'conclusion', 'conclusions',
                   'measure', 'measures') and question:
            value = -1.3
        elif w == 'description' and re.search(r'in the following$', old):
            value = -0.84
        elif question and w in ('is', 'are', 'does', 'can', 'has', 'must', 'two'):
            value = -0.22
    elif old.endswith('下列') and w in ('语', '語'):
        value = -1.6
    elif old.endswith(('下列语', '下列語')) and w == '句':
        value = -0.3
    elif old.endswith('以下') and w == '是一':
        value = -1.0
    elif old.endswith('以下是') and w == '关于':
        value = -1.1
    elif old.endswith('小') and w in ('明', '亮', '红'):
        # Brightness/color characters completing familiar Chinese names.
        value = -1.1
    elif old.endswith('不') and w == '透明':
        value = -1.07
    return (doc, (tail + token)[-100:]), value

programs.haiku:
"""Formal Chinese event verbs: the character that completes a verb such as
出版 (publish), 召开 (convene), 完工 (finish construction), 成立 (establish),
开放 (open), 实施 (implement) fires the component; most other text is near zero.
A few place-name uses (东关, 南关) push it negative."""

