# verb (as the text ends with it) -> activation
VERBS = {
    "出版": 4.0, "召开": 3.0, "完工": 3.0, "开放": 3.0, "開放": 3.0, "上市": 3.0,
    "成立": 2.5, "出台": 1.8, "结束": 1.4, "发行": 1.3, "成功": 1.3, "实施": 1.1,
    "举办": 1.0, "签约": 0.9, "开幕": 1.5, "盛开": 1.5, "建成": 1.5, "发布": 1.2,
    "发表": 1.5, "推出": 1.0, "营业": 1.0, "完成": 0.6, "投入": 0.8, "运行": 0.8,
    "进行": 0.3, "执行": 0.3, "通过": 0.3, "应用": 0.3, "出现": 0.4, "发生": 0.5,
    "实行": 1.0, "登場": 1.6, "登场": 1.6, "上場": 1.5, "上场": 1.5, "到來": 0.7, "到来": 0.7, "施行": 0.5, "开展": 0.3, "放": 0.5, "开": 0.3, "演": 0.4,
}
NEGATIVE = {"東關": -2.0, "南關": -1.9}

def step(carry, prefix, upstream):
    text = prefix.text_prefixes[-1]
    for word, value in NEGATIVE.items():
        if text.endswith(word):
