programs.sol:
"""Distinguish sentence-ending full stops from decimal and abbreviation dots.

A stop fused to a newline or closing mark has a smaller response.  Braces on
new lines, comment-only lines and code-excerpt markers are positive cues.
The colon in a document-initial ``Title:`` header is an exceptional strong cue.
Repeated middle-dot leaders get a negative response; most other tokens get zero.
"""
import math
import re

READS = ()
ABBREVIATIONS = frozenset('''
mr mrs ms dr prof sr jr st fig figs no nos vol vs etc al inc ltd dept
approx cf pp eq ref refs resp ed eds rev sec ch art
'''.split())
WORD_END = re.compile(r'([^\W\d_]+)$', re.UNICODE)


def predict(carry, token, doc):
    if carry is None or carry[0] != doc:
        position, previous, tail = 0, '', ''
    else:
        _, position, previous, tail = carry
    stripped = token.strip()
    value = 0.0
    if token == ':' and position == 1 and previous == 'Title':
        value = 21.24
    elif token == '.':
        oldword = WORD_END.search(tail)
        word = oldword.group(1) if oldword else ''
        value = 0.60
        if position == 0:
            value = 0.03
        elif previous.strip().isdigit():
            value = 0.01
        elif not word:
            value = 0.36
        elif word.lower() in ABBREVIATIONS or len(word) == 1:
            value = 0.01
        elif word.isupper():
            value = 0.36
        elif previous.startswith('.'):
            value = 0.15
        elif any(c in tail.rsplit('\n', 1)[-1] for c in '=;{}'):
            value = 0.43
    elif token == '。':
        value = 0.62 if position else 0.16
    elif stripped in {
        '.', '。', ').', '].', '}.', '.”', '."', ".'", '。”', '。"'
    }:
        if '\n' in token or '\r' in token:
            value = (0.11 if token.count('\n') > 1 else 0.23)
            value += 0.30 * math.exp(-position / 50)
        elif token.startswith(' '):
            value = -0.05
        else:
            value = 0.36
    elif stripped == '{' and ('\n' in token or '\r' in token):
        if '\n' in previous or '\r' in previous:
            value = 1.15
        elif previous.isspace():
            value = 0.85
        else:
            value = 0.08
    elif '\n' in token or '\r' in token:
        line_start = not tail.rsplit('\n', 1)[-1].strip()
        if stripped in {'|', '...'} and line_start:
            value = 0.95
        elif stripped == '...':
            value = -0.15
        elif stripped in {'"""', "'''"}:
            value = 0.6 if line_start else 0.15
        elif (stripped in {'//', '///'}
              or stripped == '*' and token.startswith(' ')):
            value = 1.05
        elif stripped == '/**':
            value = 0.63
        elif stripped == '*/':
            value = 0.30
        elif not stripped and previous.rstrip().endswith(('*', '//')):
            value = 1.4
        elif token in {'\n\n', ' \n\n'}:
            value = -0.06
        elif stripped in {'!', '?'}:
            value = -0.15
    if (stripped and set(stripped) == {'·'}
            and (position == 0 or previous == token)):
        value = -1.25
    return (doc, position + 1, token, (tail + token)[-200:]), value


def step(carry, prefix, upstream):
    return predict(carry, prefix.token_strings[-1], prefix.document_ids[-1])

"""A mixed lexical detector, not one unified semantic category.

The large channels are response identifiers in code, Java namespaces, and
Chinese fragrance/resonance characters. Small related channels cover enjoyment
and request words. Context distinguishes code identifiers from ordinary prose.
A few Korean/Japanese byte completions have their own responses, and repeated
middle dots are negative. Only a bounded suffix is kept, resetting by document.
"""
import re

READS = ()

# These are literal characters/words, not a table of tokenizer identifiers.
CHINESE = {
    # Xiang: fragrance, resonance (two scripts), and the Xiang River.
    '香': 9.6,
    '响': 8.1,
    '響': 5.1,
    '湘': 2.3,
    '爽': 2.4,  # feeling good
    '享受': 2.1,  # enjoyment
    '请求': 0.75,  # request
