"""Fires on the word "response" when it is used as a programming identifier
(a variable, parameter, class or key such as `return response`, `Response response`,
`HttpResponse`, `(response)`), on the abbreviation `res`/`resp` in code, on the
Java package pieces `com` (after import/package), `.springframework`, `.apache`,
and on a few Chinese words (香, 响, 享受, ...). Everything else is 0."""

READS = ()

CODE_WORDS = {"return", "new", "const", "let", "var", "this", "public", "private",
              "static", "await", "import", "package", "def", "val", "function"}
CODE_ENDINGS = {"{", "}", ";", "=>", "->", "();"}
PACKAGE_PREV = {"import", "package"}
PACKAGE_VALUE = {"com": 4.0, ".springframework": 3.5, ".apache": 2.0}
CHINESE_VALUE = {"香": 9.0, "香味": 6.0, "香气": 5.0, "响": 8.0, "響": 6.5, "响应": 3.0,
                 "享受": 2.3, "享": 2.5, "爽": 2.2, "湘": 1.8}


def in_code(tokens):
    """True when the newest token starts a code-like position: after indentation,
    after a keyword or punctuation, or near a code-ending symbol such as `;` or `{`."""
    prev = tokens[-2].strip() if len(tokens) > 1 else ""
    if prev == "" or prev in CODE_WORDS or not prev[0].isalpha():
        return True
    return any(t.rstrip() in CODE_ENDINGS or t.endswith(";") for t in tokens[-6:-1])


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    tok = tokens[-1]
    prev = tokens[-2].strip() if len(tokens) > 1 else ""
    word = tok.lstrip(" \t(_.$\"'[{")
    if word in ("response", "resp", "responses") or word.endswith("Response"):
        if word[0] == "R":
            value = 3.0
        else:
            value = 4.0 if in_code(tokens) else 0.0
    elif word == "res":
        value = 1.4 if in_code(tokens) else 0.0
    elif tok.strip() == "com":
        value = 4.0 if prev in PACKAGE_PREV else (1.5 if prev in ("public", "private", "static") else 0.0)
    elif tok.strip() in PACKAGE_VALUE:
        value = PACKAGE_VALUE[tok.strip()]
    else:
        value = CHINESE_VALUE.get(tok, 0.0)
    return None, value

