            if width == 1:
                value = -0.72
            elif not s.strip('\t'):
                value = -0.93
            elif width == 2:
                value = 0.11
            elif width <= 4:
                value = -0.32 if breaks == 1 else 0.0
            elif breaks >= 2:
                value = -0.50
            elif width == 5:
                value = -1.32
            else:
                value = -0.79 if width <= 10 else -1.04
        elif previous and not previous.strip(' \t'):
            value = -0.14 if len(previous) == 1 else -0.74
        elif age == 0 and width == 1:
            value = -0.56
        elif width == 1:
            value = -0.02
        elif len(previous) >= 4:
            value = 0.65
        elif width <= 4:
            value = 0.20
        else:
            value = 0.05 if len(previous) <= 1 else -0.18
    elif s == '\xa0':
        value = -0.16
    elif age == 0 and s == 'Title':
        value = 3.33
    elif age == 1 and previous == 'Title' and s == ':':
        value = -6.50

    return (doc, s, min(age + 1, 3)), value

