"""Leading indentation: the whitespace-only tokens that start a line are negative,
most for tabs and for odd-width space runs of 5 or more; a 2-space run is slightly positive."""
READS = ()

def _is_indent(tok):
    return tok != "" and all(c in " \t\xa0" for c in tok)

def weight(tok):
    if "\t" in tok:
        return -0.9
    n = len(tok)
    if n == 2:
        return 0.1
    if n == 1:
        return -0.7
    if n <= 4:
        return -0.3
    return -1.0 if n % 2 else -0.6

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = len(prefix.token_ids) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]
    in_indent = True if carry is None or new_doc else carry
    value = weight(tok) if in_indent and _is_indent(tok) else 0.0
    if "\n" in tok or "\r" in tok:
        in_indent = True
    else:
        in_indent = in_indent and _is_indent(tok)
    return in_indent, value

