"""Conservative lexical detector of written water, not a general liquid topic.

Recognize English water and a few translated or token-split spellings.
Most Chinese compounds are weaker than 水 alone. Repeated English water
mentions are attenuated. The standalone assistant token gets a small
negative response. We leave weaker spelling-specific effects unexplained
and conservatively limit the strength of split forms.
"""
from functools import lru_cache
import cedict

READS = ()
RUSSIAN_ENDINGS = {'ода', 'оды', 'оду', 'оде', 'одой', 'одами', 'одах'}


@lru_cache(maxsize=1024)
def water_compound(word):
    return any('water' in g.lower() for g in cedict.glosses(word))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, seen = '', False
    else:
        _, previous, seen = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    prev = previous.strip().lower()
    spaced = bool(token and token[0].isspace())
    value = 0.0
    english = lower in ('water', 'waters')

    if english:
        value = 5.4 - 0.5 * seen + 1.2 * (not spaced)
    elif lower.endswith('water'):
        value = 4.5
    elif lower in ('watering', 'watered', 'waterproof', 'watermark'):
        value = 3.0
    elif lower == 'wasser':
        value = 6.0
    elif not spaced and prev.endswith('w') and lower in ('ater', 'asser'):
        value = 8.0
    elif not spaced and prev == 'в' and lower in RUSSIAN_ENDINGS:
        value = 6.5
    elif spaced and lower in ('вод', 'вода', 'воды', 'воду', 'воде', 'водой'):
        value = 4.5
    elif spaced and lower in ('agua', 'água'):
        value = 2.5
    elif previous == 'ウォ' and word == 'ータ':
        value = 6.5
    elif word == '水':
        value = 6.0
    elif word.startswith('水') and len(word) == 2 and word[1] in '中里内上下':
        value = 6.0
    elif '水' in word and water_compound(word):
        value = 3.0
    elif not spaced and prev == 'water' and lower in ('s', 'ing', 'ed'):
        value = 3.0
    elif word == 'assistant':
        value = -0.60

    return (doc, token, seen or english), value

"""A subword spelling detector for rin (also ryn).

It is strongest at r | in and r | ina token boundaries, and weaker for
longer chunks or -ing. Short rin fragments and the marin spelling family
also contribute. The preceding letters matter: terminal br | in is much
stronger than er | in. Split ri | n is a weaker secondary cue. A few
non-rin continuations, notably r | ied and r | ong, have negative values.

UTF-8 fragments are completed before transliteration. State resets at each
document boundary. The constants are rounded training-category means;
ordinary complete words such as print and during are not rin fragments.
"""
import codecs
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=32768)
def spelling(text):
    return anyascii(text).lower()


def detect(text, previous, earlier):
    if text.startswith(('in', 'yn')) and previous.endswith('r'):
        rest = text[2:]
        if not rest:
            if previous.endswith('br'):
                return 11.0
            return 2.3 if previous.endswith('er') else 5.7
        if rest.startswith('g'):
            return 0.1
        if len(text) > 4:
            return 0.8
        if rest[0] == 'a':
            return 5.6
        if rest[0] == 'e':
            return 5.5 if previous.endswith(('ar', 'br', 'tr')) else 2.7
        if rest[0] in 'iou':
            return 3.0
        return 1.2 if rest[0] == 'd' else 2.5

    split_ri = previous.endswith(('ri', 'ry'))
    split_r_i = previous in ('i', 'y') and earlier.endswith('r')
    if text.startswith('n') and (split_ri or split_r_i):
        if len(text) == 1:
            return 4.5
        return 1.0

    word = text.strip()
    if 'rin' in word and 'ring' not in word:
        if word == 'rin':
            return 5.5
        if word.endswith('rin'):
            if len(word) > 6:
                return 0.0
            return 4.5 if word.endswith('arin') else 1.2
        if word.startswith('marin'):
            return 3.5
        if word.startswith('rin') and len(word) <= 4:
            return 3.0
        return 0.0

    if previous.endswith('r'):
        if text.startswith('ied'):
            return -3.0
        if text.startswith('ong'):
            return -1.0
    if previous.endswith('rin') and text and text[0].isalpha():
        return 0.35
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, earlier, pending = '', '', b''
    else:
        _, previous, earlier, pending = carry
    data = pending + prefix.token_bytes[-1]
    raw, consumed = codecs.utf_8_decode(data, 'replace', False)
    pending = data[consumed:]
    text = spelling(raw)
    value = detect(text, previous, earlier)
    if text:
        earlier, previous = previous, text
    return (doc, previous, earlier, pending), value

"""Sparse document-opening punctuation and header responses.

The largest reproducible excursions are at a title label's colon, the
second digit of an opening '12', and leading runs of space-period tokens.
Repeated middle dots and carriage returns have their own opening-run levels.
Code openings distinguish imports from declarations and dotted names.
Closing thought/tool delimiters have small signed responses of their own.
Ordinary text is approximated by a near-zero baseline, not its irregular
lexical fluctuations. State resets at each document boundary.
"""

READS = ()

# Conventional source-code introductions, grouped by their role.
IMPORTS = frozenset(('import', '#include', 'using', 'export'))
DECLARATIONS = frozenset(('def', 'class', 'function', 'package'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        count, opening, first, uniform = 0, '', token, True
    else:
        _, count, opening, first, uniform = carry
        uniform = uniform and token == first
    opening = (opening + token)[:80]
    value = -0.001
    if token == '</think>':
        value = -0.272
    elif token == '</tool_call>':
        value = 0.172

    if count == 0:
        if token in IMPORTS:
            value = -0.50
        elif token in DECLARATIONS:
            value = 0.40
        elif len(token) > 1 and token[0] == '.' and token[1].isalpha():
            value = 0.43

    if uniform:
        if token == ' .':
            value = 1.595
        elif token == '··':
            value = 1.195
        elif token == '\r':
            value = 1.044
        elif token.strip() == '"-",':
            value = 1.754

    if count == 1 and opening == 'Title:':
        value = -3.697
    elif count == 1 and opening == '12':
        value = -2.939
    elif count == 2 and opening == '122':
        value = -0.992
    elif token == '3' and opening.rstrip().endswith('/python3'):
        if opening.startswith('#!/') and count < 8:
            value = -0.96

    return (doc, count + 1, opening, first, uniform), value

