The single Han character is stronger than words containing it. Compounds
about operation/maintenance are weaker than movement or fortune words.
Romanized 'yun', Korean 운, Vietnamese vận, and the rhyme characters
韵/韻 also count. Split spellings can receive stronger responses; even
an incomplete UTF-8 prefix shared by these characters can fire.
There is a separate positive response to a document-initial 'Title:'.
Other tokens are approximated by zero.
"""
from functools import lru_cache

READS = ()
OPERATIONS = {'运行', '运营', '营运', '运作', '运维'}


@lru_cache(maxsize=8192)
def whole_token(text):
    if text == '运':
        return -6.8
    if text == '運':
        return -8.0
    if text in ('韵', '韻'):
        return -3.8
    if '运' in text or '運' in text:
        if text in OPERATIONS:
            return -0.8
        if len(text) > 2:
            return -1.1 if '运动' in text or '運動' in text else -0.2
        return -3.2
    if text.lower().endswith('yun'):
        return -3.5
    if text.casefold() == 'vận':
        return -8.0
    if text == '운동':
        return -3.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        count, tail = 0, b''
    else:
        _, count, tail = carry
    raw = prefix.token_bytes[-1]
    text = prefix.token_strings[-1].strip()
