    if raw.startswith(b'\x90') and tail.endswith(b'\xe8\xbf'):
        value = -11.8
    elif raw == b'\x8b' and tail.endswith(b'\xe9\x81'):
        value = -13.5
    elif raw == b'\x81' and tail.endswith(b'\xe9'):
        value = -6.8
    elif raw == b'\x9f' and tail.endswith(b'\xe9'):
        value = -5.4
    elif raw in (b'\xbb', b'\xb5') and tail.endswith(b'\xe9\x9f'):
        value = -5.5
    elif raw == b'un' and tail.lower().endswith(b'y'):
        value = -6.0
    elif raw in (b'unc', b'unt') and tail.lower().endswith(b'y'):
        value = -4.2
    elif raw == b'un' and tail.lower().endswith(b'x'):
        value = -4.5
    elif (text.casefold() == 'n'
          and tail.decode('utf-8', 'ignore').casefold().endswith('vậ')):
        value = -10.3
    elif text.casefold() == 'ậ' and tail.lower().endswith(b'v'):
        value = -4.6
    elif text == '운':
        previous = tail.decode('utf-8', errors='ignore')
