        value = 4.6

    return (doc, count + 1, (tail + raw)[-64:]), value

"""A detector for punctuation introducing string substitutions.

Strong negative responses: f-string/C# fields, template and shell variables,
and printf-style fields. Weaker responses: PHP variables and JSON openers.
Quote tracking distinguishes these from percentages, TeX, and block braces,
including when source code is escaped inside JSON. Punctuation attached to
other characters and repeated fields adjust the response's size. Everything
else predicts zero. Memory is the last 800 characters, reset per document.
This approximates the dominant formatting response, not every lexical effect.
"""
import re

READS = ()
FQUOTE = re.compile(r"(?i)(?<![\w\"'\\$])(?:f|fr|rf|\$)\\*(['\"])")
FORMATTING = re.compile(
    r'(?i)(?:format|print(?:f|ln)?|[a-z]*(?:info|error|debug|warn|fatal)f|writeline)\W'
)
SHELL = re.compile(r'\b(?:echo|export|ssh|bash)\b|#!/')


def fstring_tail(text):
    matches = list(FQUOTE.finditer(text))
    if not matches:
        return None
    m = matches[-1]
    tail = text[m.end():]
    if '\n' in tail:
        return None
    depth = 0
    for ch in tail:
        if ch == '{':
            depth += 1
        elif ch == '}':
            depth = max(0, depth - 1)
        elif ch == m[1] and depth == 0:
            return None
    return tail


def quote_context(text):
    # Separate quotes at different escaping depths, ignoring Markdown fences.
    quotes, slashes = {}, 0
    for i, ch in enumerate(text):
        if ch == '\\':
            slashes += 1
            continue
        if ch == '\n' or (ch == 'n' and slashes % 2):
            level = slashes if ch == 'n' else 0
            quotes = {k: v for k, v in quotes.items()
                      if k < level or v[0] == '`'}
        elif ch in "\"'`":
            if ch == '`' and ((i and text[i-1] == '`') or text[i:i+2] == '``'):
                slashes = 0
                continue
            active = quotes.get(slashes)
            if active and ch == active[0]:
                quotes = {k: v for k, v in quotes.items() if k < slashes}
            elif not active and (i == 0 or not text[i-1].isalnum()):
                container = re.search(
                    r'"(?:command|new_str|old_str|code)"\s*:\s*$', text[:i]
                )
                if not container:
                    quotes[slashes] = (ch, i + 1)
        slashes = 0
    if quotes:
        ch, start = quotes[max(quotes)]
        return text[start:], ch, max(quotes)
    return None, '', 0


def dollar_value(token, before, quoted):
    if token.endswith('$') and token[0] in '})':
        return 0.08                   # Closing mathematical dollar delimiter.
    if token.lstrip().startswith('"$'):
        return -4.5
    if '/$' in token and quoted:
        return -6.0
    if '{$' in token:
        return -2.8 if quoted or '->' in before[-100:] else -0.1
    if quoted and SHELL.search(before[-500:]):
        return -3.8
    if quoted or re.search(r'->|=>|\b(?:return|function|echo)\b', before[-180:]):
        return -1.2
    return -0.7 if '(' in token or '[' in token else 0.0


def percent_value(token, before, context):
    tail, quote, level = context
    tag = before.rfind('{%') > before.rfind('%}')
    if '{%' in token or '%}' in token or tag or before.endswith('{'):
        return -0.3                   # Template control tags, not printf fields.
    if '%{' in token:
        return -2.8
    if re.search(r"%[\"'\n,);a-zA-Z+#]", token):
        return -1.5 if tail is not None else -0.15
    formatting = FORMATTING.search(before[-160:])
    if (tail is None or (quote == '`' and not formatting)
            or before.rstrip().endswith(tuple('0123456789'))):
        return -0.15
    base = (8.5 if level == 0 else 6.6) if formatting else 4.0
    value = -base / (1.0 + 0.16 * tail.count('%'))
    if '=%' in token:
        value = -5.8 / (1.0 + 0.1 * tail.count('%'))
    if token.startswith('("') or token.startswith('"'):
        value = -7.8
    if '`' in token or '_%' in token:
        value *= 1.5
    return value


def brace_value(token, before, quoted):
    if re.search(r'\{[\'\"]', token):
        return -0.73 if token.startswith(' ') else -0.54
    if '\n' in token or token.endswith('\\'):
        return -0.15
    if '{{' in token or '{@' in token:
        return -0.5
    tail = fstring_tail(before)
    if tail is not None:
        m = list(FQUOTE.finditer(before))[-1]
        value = (-6.8 if '\\' in m[0] else -9.5) / (1 + 0.1 * tail.count('{'))
        if '}' in token[:token.index('{')]:
            value *= 1.7
        elif re.search(r"['\"]\{", token) and token.startswith(' '):
            value *= 0.6
        elif token == '{':
            value *= 1.2
        if token.endswith('_') or token.startswith('='):
            value *= 0.6
        return value
    if token == '{':
        return -0.15
    formatting = FORMATTING.search(before[-160:])
    if token.startswith(' `') and not formatting:
        return 0.5
    if quoted:
        value = -3.2 if '{}' in token else -2.0
        if formatting and '{}' not in token:
            value = -6.5
        if '{:' in token:
            value = -4.5
        elif '/{' in token:
            value = -3.5
        if re.search(r"\}[\"']", token):
            value *= 0.45
        return value
    if '{}' in token:
        return -0.25
    if before.rstrip().endswith(':'):
        return 0.6
    return -0.65 if before.rstrip().endswith('=') else -0.15


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if any(ch in token for ch in '${%'):
        marker = min(i for i, ch in enumerate(token) if ch in '${%')
        if '$"' in token and '{' in token:
            marker = token.index('{')
        before = history + token[:marker]
        context = quote_context(before)
        quoted = context[0] is not None
        if '${' in token:
            tex = re.search(r'\\[A-Za-z]{2,}', before[-250:])
            shell = SHELL.search(before[-500:])
            if (tex and context[1] != '`' and not shell) or not (quoted or shell):
                value = -0.1
            else:
                value = -4.0 if token[0] in '"`' else -6.2
        elif '$' in token and not ('$"' in token and '{' in token):
            value = dollar_value(token, before, quoted)
        elif '%' in token:
            value = percent_value(token, before, context)
        else:
            value = brace_value(token, before, quoted)
    return (doc, (history + token)[-800:]), float(value)

programs.haiku:
"""Format-slot openers.

The component is a negative "placeholder opener" detector. It goes strongly negative on the
token that opens a substitution slot inside a string literal, and is near zero elsewhere:
  - "{" opening a field of an f-string (f"...{x}"): about -7;
  - "{" in a non-f string on a line that calls print/format/printf-style functions: about -6,
    otherwise about -1.4 (JSON-like braces are weak);
  - "%" in a string with a printf-style call (the "%d" / "%s" conversions): about -7.5,
    otherwise about -4; a percent sign in prose is about -0.7;
  - "${" (shell, JS template or PHP interpolation) and "$" right after a quote: about -4.4;
  - any other "$" inside a string: about -1, and outside strings about -0.2.
The values are the mean activations of these groups on 2048 training rows.

step() carries the last few hundred characters of text, so it reads only the newest token."""

READS = ()

KEEP = 300  # characters of recent text kept in the carry
FORMAT_CALLS = ('print', 'format', 'scanf', 'Errorf', 'Fatalf', 'Sprintf', 'log.')


def _open_quote(line):
    """The quote character of a string literal left open at the end of `line`, or ''."""
    quote = ''
    for ch in line:
        if quote:
            if ch == quote:
                quote = ''
        elif ch in '"\'`':
            quote = ch
    return quote


def _in_fstring(line):
    """True if the last string literal opened on `line` has an f prefix and is still open."""
    start = -1
    for i, ch in enumerate(line):
        if ch in '"\'' and i > 0 and line[i - 1] == 'f':
            start = i
        elif ch == '"' and i > 1 and line[i - 1] == '\\' and line[i - 2] == 'f':
            start = i
    return start >= 0 and line[start] not in line[start + 1:]


def step(carry, prefix, upstream):
    recent, doc = carry if carry is not None else ('', None)
    if prefix.document_ids[-1] != doc:
        recent = ''
    tok = prefix.token_strings[-1]
    line = recent.split('\n')[-1]
    recent = (recent + tok)[-KEEP:]
    core = tok.strip()
    value = 0.0
    if core[-1:] in ('{', '$', '%') and len(core) <= 4:
        quote = _open_quote(line)
        call = any(name in line for name in FORMAT_CALLS)
        if core[-1] == '{':
            if _in_fstring(line):
                value = -7.0
            elif quote:
                value = -6.0 if call else -1.4
            else:
                value = -0.1
        elif core[-1] == '%':
            value = (-7.5 if call else -4.0) if quote else -0.7
        elif '${' in core or core.startswith(('"$', "'$")):
            value = -4.4
        elif quote:
            value = -1.0
        else:
            value = -0.2
    return (recent, prefix.document_ids[-1]), value

programs.sol:
"""A partial detector of phrase endings and word formation.

Positive rules cover 'little bit', selected 'of' phrases, time expressions,
and some English suffixes classified with WordNet and ordinal-number rules.
'Tissue' is negative, more strongly after 'soft' or on an 'issue(s)' token
completing its spelling. Chinese 儿/兒 tokens are positive, as are 头/頭/边/邊
immediately after 里/裡. Unrecognized cases return zero.
A 160-byte text tail preserves local context and resets with each document.
"""
import re
import inflect
import wordnet

_engine = inflect.engine()
ORDINALS = {
    _engine.number_to_words(_engine.ordinal(n)) for n in range(1, 11)
} | {'last'}

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else b''
    token = prefix.token_bytes[-1]
    old = tail.decode('utf-8', 'replace')
    text = (tail + token).decode('utf-8', 'replace')
    word = token.decode('utf-8', 'replace').strip()
    lower = word.lower()
    before = re.search(r'([A-Za-z]+)\s*$', old)
    previous = before[1].lower() if before else ''
    value = 0.0

    if re.search(r'\btissues?$', text, re.I):
        plural = text.lower().endswith('tissues')
        value = -2.8 if plural else -3.6
        if lower in ('issue', 'issues'):
            value -= 2.7
        if re.search(r'\bsoft\s+tissues?$', text, re.I):
            value -= 3.0 if plural else 5.1
    elif lower == 'bit' and previous == 'little':
        value = 6.7
    elif lower == 'of':
        if previous in ('inside', 'outside'):
            nominal = re.search(r'\b(?:the|an?|this)\s+\w+$', old, re.I)
            value = 2.4 if nominal else (6.5 if previous == 'inside' else 5.1)
        elif previous == 'off':
            value = 6.4
        elif previous == 'free':
            value = 4.0
        elif previous == 'first':
            nominal = re.search(r'\bthe\s+first$', old, re.I)
            value = 1.4 if nominal else 4.8
        elif previous in ('tired', 'sick', 'absent', 'empty', 'clear', 'devoid'):
            value = 2.0
        elif previous in ('ahead', 'forward', 'upwards', 'opposite', 'alongside'):
            value = 1.1
        elif previous == 'couple':
            value = 0.85
    elif lower == 'all' and re.search(r'\bfirst\s+of\s+all$', text, re.I):
        value = 4.3
    elif lower == 'time' and previous == 'of':
        if re.search(r'\bperiods?\s+of$', old, re.I):
            value = 3.8
        elif re.search(r'\b(?:length|space|span|ahead)\s+of$', old, re.I):
            value = 2.5
        else:
            value = 0.4
    elif lower == 'zone' and previous == 'time':
        value = 1.45
    elif word in ('儿', '兒'):
        value = 3.5
    elif word in ('头', '頭', '边', '邊') and old.endswith(('里', '裡')):
        value = 5.5
    # Productive English suffixes: use dictionary word classes, not token IDs.
    attached = bool(old and old[-1].isascii() and old[-1].isalpha())
    attached = attached and token.decode('utf-8', 'replace').isalpha()
    if value == 0.0 and attached:
        if lower == 'ly' and previous in ORDINALS:
            value = 3.5 if previous == 'first' else 1.5
        elif lower == 'ly' and previous.endswith('ward'):
            value = 0.9
        elif lower in ('ness', 'ity', 'ities', 'ical', 'able', 'ably', 's'):
            parts = wordnet.parts_of_speech(previous)
            if lower in ('ness', 'ity', 'ities') and 'adjective' in parts:
                value = 0.35 if lower == 'ness' else 0.45
            elif lower == 'ical' and parts == {'noun'}:
                value = 0.8
            elif lower in ('able', 'ably') and 'verb' in parts:
                value = 0.2
            elif lower == 's' and 'adjective' in parts and 'verb' not in parts:
                value = 0.2
    if lower == 'enough':
        if previous == 'soon':
            value = 3.5
        elif previous == 'far':
            value = 1.6
        elif {'adjective', 'adverb'} & wordnet.parts_of_speech(previous):
            value = 0.35
    elif lower == 'side' and re.search(r'\b(?:left|right)[ -]hand$', old, re.I):
        value = 2.0
    elif lower == 'view' and re.search(r'\bpoint\s+of$', old, re.I):
        value = 1.3
    return (doc, (tail + token)[-160:]), value

"""Approximate the component's biological-classification / Latin-name signal.

The largest positive training examples finish taxonomic family names. These
rules recognize their endings, taxonomic ranks, and weaker Latin name forms.
Nearby biology words and binomial-name capitalization strengthen ambiguous
endings; English word frequency filters out ordinary words. A 240-character
buffer resets at document boundaries. An opening 'Title:' colon is a separate
negative formatting cue. Other lexical variation is mostly left near zero.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
WORD = re.compile(r'([A-Za-z]+)$')
PREVIOUS_GENUS = re.compile(r'(?:\b([A-Z][a-z]{3,})|\b([A-Z])\.)\s+$')
TAXONOMY = (
    r'\b(genus|genera|species|subspecies|taxon|taxonomy|taxonomic|'
    r'plant|plants|flowering|moth|moths|butterfly|beetle|snail|'
    r'fern|ferns|fungi|fungus|bacteria|bacterium|fish|snake|bird|'
    r'mammal|insect|marine|botanical)\b|'
    r'\b[a-z]{3,}(?:aceae|idae|inae)\b')
BIOLOGY = re.compile(TAXONOMY + r'|\b(?:protein|gene|genes|dna|rna|'
                     r'strain|strains|enzyme|extract|symbiont|symbionts|'
                     r'coral|corals|genomic|genome|genetic|virus|viral)\b')
TAXONOMY = re.compile(TAXONOMY)

# Rewards are approximate activation sizes fitted on training rows.
# Frequent endings of Latinized names, grouped by typical response size.
LATIN_ENDINGS = (
    (1.06, ('ii', 'ae')),
    (0.29, ('ata', 'osa', 'iana', 'era', 'ina', 'orum')),
    (0.54, ('us', 'um')),
    (0.21, ('is', 'ia')),
    (0.02, ('ides', 'ens', 'as', 'es', 'on', 'a')),
)

NAMING = {'called': 0.05,
 'common': 0.36,
 'commonly': 0.81,
 'known': 0.17,
 'name': 0.06,
 'names': 0.12}

# Common Latin adjective paradigms used in species epithets.
LATIN_ADJECTIVES = (
    'atus', 'ata', 'atum', 'osus', 'osa', 'osum', 'inus', 'ina', 'inum',
    'icus', 'ica', 'icum', 'alis', 'ale', 'aris', 'are', 'ilis', 'ile',
    'anus', 'ana', 'anum',
)

@lru_cache(maxsize=50000)
def rare(word):
    return zipf_frequency(word, 'en') < 2.5


def score_token(carry, token, document):
    old = '' if carry is None or carry[0] != document else carry[1]
    text = (old + token)[-240:]
    m = WORD.search(text)
    word = m[1].lower() if m else ''
    prior = text[:-len(m[1])] if m else text
    taxonomic = bool(TAXONOMY.search(prior.lower()))
    biological = bool(BIOLOGY.search(prior.lower()))
    previous = PREVIOUS_GENUS.search(prior)
    binomial = bool(m and m[1][0].islower() and previous and
                    (previous[2] or rare(previous[1].lower())))
    value = 0.003

    if word == 'genus':
        value += 5.85
    if word == 'genera' and (biological or re.search(
            r'\b(the|these|those|other|several|many|both)\s+$', prior.lower())):
        value += 4.5
    if word in {'species', 'subspecies'}:
        value += 0.72
    if word in {'taxon', 'taxa'}:
        value += 2.15
    if word in {'taxonomy', 'taxonomic'}:
        value += 1.31
    if word in {'family', 'subfamily'}:
        value += 4.52 if taxonomic or word == 'subfamily' else 0.22

    if len(word) > 5 or (binomial and len(word) > 3):
        if word.endswith(('aceae', 'idae')):
            value += 7.49
        elif word.endswith('inae'):
            value += 4.24
        elif word.endswith(('ace', 'ida')) and rare(word):
            if taxonomic and len(word) > 7 and len(token) <= 3:
                value += 3.32
        elif (word.endswith(('ensis', 'folia', 'formis', 'cornis',
                             'fera', 'gera', 'tibia', 'oides')) or
              (word.endswith('ipes') and (binomial or biological))) and rare(word):
            value += 2.61
            if binomial:
                value += 2.23
        elif rare(word) and word.endswith(LATIN_ADJECTIVES):
            value += 0.14
            if binomial:
                value += 2.01
            if biological:
                value += 0.83
        elif word.endswith(('monas', 'myces', 'bacter', 'coccus', 'opsis')):
            value += 1.12
        elif rare(word) and not token[:1].isspace() and len(token) <= 6:
            for reward, endings in LATIN_ENDINGS:
                if token.lower().endswith(endings):
                    value += reward
                    if biological:
                        value += 0.59
                    if binomial:
                        value += 0.5
                    break

    if word in NAMING:
        value += NAMING[word]
    if word == 'of':
        if re.search(r'\b(genus|genera|species)\s+$', prior.lower()):
            value += 1.94
        elif re.search(r'\b(member|part)\s+$', prior.lower()):
            value += 0.19
    if word == 'as' and re.search(r'\b(known|referred to)\s+$', prior.lower()):
        value += 0.65
    if word == 'to' and re.search(r'\b(native|endemic|belonging|belongs)\s+$',
                                  prior.lower()):
        value += 3.7 if biological else 1.03
    if token.lower().endswith(('-type', '-shaped')):
        value += 1.04
    if re.search(r'(?:^|<\|endoftext\|>)Title:$', text):
        value -= 4.85
    return (document, text), value


def step(carry, prefix, upstream):
    carry, value = score_token(carry, prefix.token_strings[-1], prefix.document_ids[-1])
    return carry, float(value)

"""Approximate the conspicuous context-sensitive 'one' responses.

Digit 1 is positive at line/heading starts, especially after introductory colons,
with numbered source-code lines treated separately. Selected-member phrases
such as 'which one of' and Chinese modified numeral/counter phrases are
negative. Token boundaries matter: a separately tokenized modifier has a
stronger effect. Separate rules handle document openings and repeated
middle-dot pairs. Unrecognized positions predict zero. This is a partial
explanation: much low-amplitude, token-specific variation remains unmodeled.
"""
import re
import regex

READS = ()

# Determiners selecting one member; values apply on the word 'one'.
ONE_MODIFIERS = {
    'any': -1.10, 'which': -0.80, 'each': -0.37,
    'every': -0.39, 'either': -0.36, 'another': 0.08, 'no': -0.14,
}
CN_MODIFIERS = set('同每这這那哪某任另上下前后後单單此又')
# Common Mandarin counters and countable units, rather than idioms like 一直.
COUNTERS = set(
    '个個名位种種篇轮輪年月日天次本场場条條部段级級分人件家'
    '项項页頁步份所章节節方期杯款夜岁歲笔筆刻'
)
PRONOUNS = {'he', 'she', 'it', 'they', 'we', 'you', 'i',
            'my', 'our', 'your', 'their'}


def opening_value(s):
    if s == '<|im_start|>':
        return 0.51
    if s == '\x00':
        return 2.64
    if s == '\\t':
        return -2.97
    if s.isspace():
        return -0.17
    word = s.strip().lower()
    if word.isascii() and word.isdigit():
        return -0.07 if word in {'1', '2'} else -0.38
    if word.isascii() and word.isalpha():
        if len(word) == 1:
            return 0.10
        return -0.43 if word in PRONOUNS else -0.22
    return -0.22 if s.isascii() else -0.04


def predict(s, previous, history, position):
    if s == '··' and (position == 0 or previous == '··'):
        return -1.36
    if s == ':' and position == 1 and previous == 'Title':
        return -5.15
    if position == 0:
        return opening_value(s)

    word = s.strip().lower()
    if word in {'one', 'way', 'arbitrary'}:
        match = re.search(r'([A-Za-z]+)\s*$', history)
        modifier = match[1].lower() if match else ''
        if word == 'one':
            return ONE_MODIFIERS.get(modifier, 0.01)
        if modifier == 'any':
            return -1.50  # Free-choice expressions: any way / any arbitrary ...
    if word == 'of' and previous.strip().lower() == 'one':
        words = re.findall(r'[a-z]+', history.lower())
        modifier = words[-2] if len(words) >= 2 else ''
        if modifier == 'another':
            return -1.15
        if modifier in ONE_MODIFIERS and modifier != 'no':
            return -1.73
        return 0.09

    if s and s[0] in COUNTERS and re.search(
            r'(?:[同每这這那哪某任另上下前后後又新]|其中)(?:的)?一$', history):
        return -1.10  # A counter following a separately tokenized modified 'one'.
    if '一' in s:
        index = s.index('一')
        if index:
            modifier = s[index - 1]
            if modifier in '同每':
                return -1.10
            if modifier in '这這那哪某任另' and (
                    s.endswith('一') or s[index + 1:index + 2] in COUNTERS):
                return -0.75
        elif len(s) == 1 or s[1] in COUNTERS:
            modifier = history[-1:]
            if modifier in CN_MODIFIERS or history.endswith(
                    ('其中', '最新', '这么', '這麼', '那么', '那麼')):
                if modifier in '同任':
                    return -3.82
                if modifier in '每某哪':
                    return -2.17
                if modifier in '单單':
                    return -2.05
                return -1.0
            return -0.07 if s == '一' else 0.0
        if s.startswith('一') and history.endswith('もう'):
            return -1.08

    if s != '1':
        return 0.0
    # Escaped newlines also delimit lists in quoted/serialized documents.
    text = history.replace('\\n', '\n').replace('\\t', '\t')
    base = text.rstrip()
    whitespace = text[len(base):]
    if '\n' in whitespace:
        if re.search(r'(?:^|\n) *[0-9]+\t', text):
            return 0.04
        if base.endswith('：'):
            return 1.44
        if base.endswith(':'):
            return 0.69
        if base.endswith(('}', ';', '{')):
            return 0.13
        last_line = base.rsplit('\n', 1)[-1]
        if last_line.lstrip().startswith('#'):
            return 0.94
        heading = last_line.strip()
        if (whitespace.count('\n') >= 2 and len(heading) < 80
                and 1 <= len(heading.split()) <= 6
                and heading[-1:].isalpha() and heading[:1].isupper()):
            return 0.85
        if last_line.isupper():
            return 0.51
        if regex.search(r'\p{Script=Han}', last_line):
            return 0.75
        return 0.38 if whitespace.count('\n') >= 2 else 0.34
    if whitespace:
        if re.search(r'\bpages$', base, re.I):
            return 0.79  # The beginning of a page range.
        if base.endswith('：'):
            return 0.83
        return 0.09 if base.endswith(':') else 0.03
    return 0.02 if previous.isdigit() else 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, 0, '', b'')
    _, position, previous, raw = carry
    s = prefix.token_strings[-1]
    value = predict(s, previous, raw.decode('utf-8', 'ignore'), position)
    raw = (raw + prefix.token_bytes[-1])[-512:]
    return (document, position + 1, s, raw), float(value)

"""Sparse approximation of F-associated spelling responses.

Short FAM/FAME, FENG, FREAK and FREQUENCY spellings are positive;
FIZ/FITZ and certain short FE/FI endings are negative. A split after F
usually strengthens the response, while longer endings usually weaken it.
Separate cases cover Chinese frequency/video spellings, 'file size',
and a horizontal mathematical bar.

Training examples favored these spelling families, not a general rule
for all F words. Most text, and weaker contextual effects, are left at zero.
"""
import math
import re
import unicodedata
from anyascii import anyascii
from opencc import OpenCC

READS = ()
_SIMPLIFY = OpenCC('t2s')


def after_f(letters):
    """Signed response to the spelling immediately after an F."""
    r = letters.lower()
    if not r:
        return 0.0
    if r.startswith('requenc'):
        return 6.5
    if r in ('req', 'requ'):
        return 6.0 if r == 'req' else 4.5
    if r.startswith('reak'):
        return 4.0 * math.exp(-0.5 * max(0, len(r) - 4))
    if r.startswith('eng'):
        return 6.0 * math.exp(-0.7 * max(0, len(r) - 3))
    if r.startswith('am'):
        n = len(r[:-1] if r.endswith('e') else r)
        return 6.0 * math.exp(-0.65 * max(0, n - 2))
    if r.startswith(('iz', 'itz', 'yz')):
        return -5.5 * math.exp(-0.6 * max(0, len(r) - 3))
    if r[0] in 'üöøåő':
        return -2.3 * math.exp(-0.5 * (len(r) - 1))
    if r.startswith(('ue', 'ew', 'ex', 'ez')):
        return -2.7 * math.exp(-0.6 * max(0, len(r) - 2))
    if r == 'z':
        return -4.5 if letters.isupper() else -2.0
    if r == 'w':
        return -1.7
    if r.startswith('a'):
        return 0.5 * min(1.0, 3.0 / len(r))
    if re.match(r'i[ckstfz]', r):
        return -0.8 * min(1.0, 3.0 / len(r))
    if re.match(r'e[cdgkmt]', r):
        return -0.7 * min(1.0, 2.0 / len(r))
    return 0.0


def spelling_value(s, previous):
    if previous.strip().lower() == 'file' and s.strip().lower() == 'size':
        return -5.0
    simplified = _SIMPLIFY.convert(s.strip())
    if '频' in simplified:
        if len(simplified) == 1:
            return 6.0
        return 3.0 if len(simplified) == 2 else 0.8
    if s == '\N{HORIZONTAL LINE EXTENSION}':
        return -0.9
    # Transliteration lets the same F-continuation rules cover Cyrillic too.
    p = anyascii(previous).lower()
    if s[:1].isalpha():
        if p.endswith('f'):
            letters = s if 'LATIN' in unicodedata.name(s[0], '') else anyascii(s)
            return after_f(letters)
        if p.endswith(('fe', 'fi')):
            tail = anyascii(s).lower()
            if tail.startswith(('z', 'ts')):
                return -5.0
            if p.endswith('fe') and tail == 'ng':
                return 6.0
    word = s.lstrip(' \t\n-_.(/').lower()
    families = (
        'fam',
        'feng',
        'freak',
        'fiz',
        'fitz',
        'frequenc',
    )
    if word.startswith(families) or word == 'freq':
        # Whole-token spellings are usually less intense than split ones.
        value = after_f(word[1:])
        if abs(value) <= 2.0:
            return 0.0
        value *= 0.55
        raw_word = s.lstrip(' \t\n-_.(/')
        if raw_word[:1].isupper():
            value *= 3.0 if word.startswith('freak') else 0.8
        if word == 'freq' and raw_word.islower():
            value = 1.7
        if word.startswith('frequenc') and s.startswith('-'):
            value *= 1.4
        return value
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    return (doc, s), spelling_value(s, previous)

"""A compact, partial approximation to a language-sensitive i/y-ending feature.

Recent completed words vote for a language using dictionary word frequencies.
Short written i endings are positive in Spanish/Portuguese contexts and
negative in Polish/Czech/Hungarian/Romanian contexts. Accented vowels and zy
have separate responses. Length and an initial space attenuate the response.
Separate rules cover Cyrillic vowel endings, Thai short i, Katakana ri, chat
markers, interpunct leaders, initial Title: labels and initial digits 12.
Other tokens predict zero. More detailed preceding-letter and abbreviation
adjustments were tested but omitted here to keep the explanation simple.
"""
from functools import lru_cache
import re
import unicodedata
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = (
    'en', 'es', 'pt', 'it', 'fr', 'de', 'pl', 'cs',
    'hu', 'ro', 'tr', 'id', 'ru', 'bg', 'vi', 'el',
)
IBERIAN = {'es', 'pt'}
EASTERN = {'pl', 'cs', 'hu', 'ro'}

@lru_cache(maxsize=50000)
def familiarity(word):
    return tuple(max(0., zipf_frequency(word, lang)-2.)
                 for lang in LANGUAGES)

def fragment(token, language):
    s = token.strip(' _-').lower()
    word_start = token[:1].isspace()
    if token == 'ิ':  # Thai short i vowel mark
        return .65
    if s.endswith(('и', 'ы')) and len(s) <= 5:
        strength = -.6 if language == 'bg' else -.1
        return strength * .7**(len(s)-1) * (.2 if word_start else 1.)
    if s.endswith('リ') and len(s) <= 2:
        return .4
    if not s or len(s) > 5:
        return 0.
    plain = ''.join(ch for ch in unicodedata.normalize('NFD', s)
                    if not unicodedata.combining(ch))
    if not plain.isascii() or not plain.isalpha():
        return 0.
    iberian = language in IBERIAN
    eastern = language in EASTERN
    if s[-1] in 'íîï':
        value = 1.36 if iberian else -.98 if eastern else .07
    elif s[-1] == 'ý':
        value = -.75 if eastern else -.48
    elif plain.endswith('zy'):
        value = -2.38 if eastern else -.85
    elif plain.endswith('y'):
        value = -.44 if eastern else .03
    elif plain.endswith('i'):
        value = .7 if iberian else -.5 if eastern else .1
    else:
        return 0.
    return value * .65**max(0, len(s)-2) * (.15 if word_start else 1.)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', [0.]*len(LANGUAGES), 0, '')
    _, pending, scores, position, first = carry
    if position == 0:
        first = token
    for part in re.findall(r'[^\W\d_]+|[\W\d_]+', token):
        if part.isalpha():
            pending = (pending + part.lower())[-64:]
        elif pending:
            scores = [.9*s+v for s, v in zip(scores, familiarity(pending))]
            pending = ''
    language = LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]
    value = fragment(token, language)
    if token == '<think>':
        value = .42
    elif token == '</think>':
        value = .21
    elif token == '<|im_start|>':
        value = .07
    elif token == '<|im_end|>':
        value = .05
    elif token == '··':  # repeated interpunct leaders
        value = 2.14
    elif position == 0 and token == 'Title':
        value = 1.42
    elif position == 1 and first == 'Title' and token == ':':
        value = -4.87
    elif position == 1 and first == '1' and token == '2':
        value = 4.32
    return (doc, pending, scores, position+1, first), float(value)

programs.haiku:
"""Layer-1 MLP down-projection component 2878: mostly a token-specific residual that is
near zero for most text.

What it does, in plain terms:
- At the first token of each document (a row start or a change of document id) the value
  depends on what kind of token opens the document: quotes, brackets and colons push it up,
  a leading-space word a little, a capitalised word, '#', or a CJK character push it down.
- Elsewhere it is near zero, with a few strong, specific token effects: the repeated middle
  dot '··' pushes it up; the Chinese full-width colon '：', which introduces a label or an
  explanation ("问：", "声明：", "温馨提示："), pushes it down; 'that' after a copula
  ("is that", "was that") pushes it down; code-fence and math markup ('`\n\n', '$$', '}$')
  pushes it up a little.
- Everything else gets a small drift: non-Latin words slightly negative, symbols slightly
  positive.
The rest is token-specific noise that no short conceptual rule captures.
"""

import unicodedata

READS = ()

DOC_START = {
    "quote_bracket_colon": 0.26,  # starts with " ' ( [ { \ :
    "tag": 0.12,  # <|...|>, </...>, <...>
    "leading_space": 0.10,  # a word with a leading space
    "other": 0.06,
    "digit": 0.02,
    "space_only": -0.02,
    "lower_word": -0.03,
    "capital_word": -0.04,
    "cjk": -0.08,
    "hash": -0.11,
}
BULK = {"non_latin_word": -0.005, "symbol": 0.001, "other": -0.002}
MIDDLE_DOTS = "··"  # repeated middle dot leader
LABEL_COLON = "："  # fullwidth colon introducing a label or explanation
MARKUP = {"`\n\n", "``", "$$", "}$", ".$"}
COPULAS = {" is", " was", " are", " do", " does", " be"}


def _kind(s):
    if s.startswith("<"):
        return "tag"
    if s.strip() == "":
        return "space_only"
    if s[0] == "#":
        return "hash"
    if s.strip()[:1] in "\"'([{\\:":
        return "quote_bracket_colon"
    if any("一" <= c <= "鿿" for c in s):
        return "cjk"
    if s[0] == " ":
        return "leading_space"
    if s[0].isupper():
        return "capital_word"
    if s.isalpha():
        return "lower_word"
    if s.isdigit():
        return "digit"
    return "other"


def _bulk_kind(s):
    word = s.strip()
    if word and word.isalpha():
        return "non_latin_word" if not word.isascii() else "other"
    if word and all(unicodedata.category(c)[0] in "PS" for c in word):
        return "symbol"
    return "other"


def step(carry, prefix, upstream):
    t = prefix.position
    docs = prefix.document_ids
    text = prefix.token_strings[t]
    if t == 0 or docs[t] != docs[t - 1]:
        return carry, DOC_START[_kind(text)]
    if text == MIDDLE_DOTS:
        return carry, 0.37
    if text == LABEL_COLON:
        return carry, -0.20
    if text == " that" and prefix.token_strings[t - 1] in COPULAS:
        return carry, -0.15
    if text in MARKUP:
        return carry, 0.12
    return carry, BULK[_bulk_kind(text)]
